function design(site, analyse) {
  const xs = [0, 4.914, 9.829, 14.743, 19.657, 24.571, 29.486, 34.4];
  const zL = -2.35, zR = 2.35, yB = -4.70;
  const nodes = [];
  const parts = [];
  const add = (a, b, group) => parts.push({ a, b, group });

  for (let i = 0; i < 8; i++) {
    nodes.push({ id: `BL${i}`, x: xs[i], y: yB, z: zL, joint: "pin" });
    nodes.push({ id: `BR${i}`, x: xs[i], y: yB, z: zR, joint: "pin" });
  }

  for (const [top, bottom] of [["L", "BL"], ["R", "BR"]]) {
    for (let i = 0; i < 7; i++) {
      add(`${top}${i}`, `${top}${i + 1}`, "TOP");
      add(`${bottom}${i}`, `${bottom}${i + 1}`, "BOTTOM");

      // Pratt diagonals point toward the bridge centre.
      if (i <= 3) add(`${top}${i}`, `${bottom}${i + 1}`, "DIAG");
      else add(`${bottom}${i}`, `${top}${i + 1}`, "DIAG");
    }
    for (let i = 0; i < 8; i++) add(`${top}${i}`, `${bottom}${i}`, "VERT");
  }

  for (let i = 0; i < 8; i++) {
    add(`L${i}`, `R${i}`, "TCROSS");
    add(`BL${i}`, `BR${i}`, "BCROSS");

    // X-braced transverse frames.
    add(`L${i}`, `BR${i}`, "FRAME");
    add(`R${i}`, `BL${i}`, "FRAME");
  }

  for (let i = 0; i < 7; i++) {
    // X bracing in both horizontal planes; the top-plane members lie on y = 0.
    add(`L${i}`, `R${i + 1}`, "TOPPLAN");
    add(`R${i}`, `L${i + 1}`, "TOPPLAN");
    add(`BL${i}`, `BR${i + 1}`, "BOTPLAN");
    add(`BR${i}`, `BL${i + 1}`, "BOTPLAN");
  }

  const heavy = "S460 CHS457x16";
  const options = {
    TOP: [
      "S460 CHS168.3x6.3", "S460 CHS193.7x8", "S460 CHS219.1x8",
      "S460 CHS244.5x8", "S460 CHS273x10", "S460 CHS323.9x10",
      "S460 CHS355.6x12.5", "S460 CHS406.4x12.5",
      "AL7075 CHS193.7x8", "AL7075 CHS219.1x8",
      "AL7075 CHS273x10", "AL7075 CHS323.9x10",
      "AL7075 CHS406.4x12.5", heavy
    ],
    BOTTOM: [
      "S460 CHS88.9x5", "S460 CHS114.3x5", "S460 CHS139.7x5",
      "S460 CHS168.3x5", "S460 CHS193.7x6.3", "S460 CHS219.1x8",
      "S460 CHS273x10", "S460 CHS323.9x10", "S460 CHS406.4x12.5",
      "AL7075 CHS114.3x5", "AL7075 CHS139.7x6.3",
      "AL7075 CHS168.3x6.3", "AL7075 CHS193.7x8",
      "AL7075 CHS244.5x8", "AL7075 CHS323.9x10", heavy
    ],
    DIAG: [
      "S460 CHS114.3x5", "S460 CHS139.7x6.3", "S460 CHS168.3x6.3",
      "S460 CHS193.7x8", "S460 CHS219.1x8", "S460 CHS244.5x8",
      "S460 CHS273x10", "S460 CHS323.9x10", "S460 CHS406.4x12.5",
      "AL7075 CHS168.3x6.3", "AL7075 CHS193.7x8",
      "AL7075 CHS244.5x8", "AL7075 CHS323.9x10", heavy
    ],
    VERT: [
      "S460 CHS76.1x4", "S460 CHS88.9x5", "S460 CHS114.3x5",
      "S460 CHS139.7x5", "S460 CHS168.3x6.3", "S460 CHS193.7x8",
      "S460 CHS273x10", "S460 CHS323.9x10",
      "AL7075 CHS114.3x5", "AL7075 CHS139.7x6.3",
      "AL7075 CHS193.7x8", "AL7075 CHS323.9x10", heavy
    ],
    FRAME: [
      "S460 CHS88.9x5", "S460 CHS114.3x5", "S460 CHS139.7x5",
      "S460 CHS168.3x6.3", "S460 CHS193.7x8", "S460 CHS219.1x8",
      "S460 CHS273x10", "S460 CHS323.9x10",
      "AL7075 CHS114.3x5", "AL7075 CHS139.7x6.3",
      "AL7075 CHS193.7x8", "AL7075 CHS273x10", heavy
    ],
    TOPPLAN: [
      "S460 CHS88.9x5", "S460 CHS114.3x5", "S460 CHS139.7x5",
      "S460 CHS168.3x6.3", "S460 CHS193.7x8", "S460 CHS219.1x8",
      "S460 CHS244.5x8", "S460 CHS323.9x10",
      "AL7075 CHS139.7x6.3", "AL7075 CHS168.3x6.3",
      "AL7075 CHS219.1x8", "AL7075 CHS323.9x10", heavy
    ],
    BOTPLAN: [
      "S460 CHS88.9x5", "S460 CHS114.3x5", "S460 CHS139.7x5",
      "S460 CHS168.3x6.3", "S460 CHS193.7x8", "S460 CHS219.1x8",
      "S460 CHS244.5x8", "S460 CHS323.9x10",
      "AL7075 CHS139.7x6.3", "AL7075 CHS168.3x6.3",
      "AL7075 CHS219.1x8", "AL7075 CHS323.9x10", heavy
    ],
    TCROSS: [
      "S460 CHS60.3x4", "S460 CHS76.1x4", "S460 CHS88.9x4",
      "S460 CHS114.3x4", "S460 CHS114.3x5", "S460 CHS139.7x5",
      "S460 CHS168.3x6.3", "S460 CHS193.7x8",
      "AL7075 CHS88.9x5", "AL7075 CHS114.3x5",
      "AL7075 CHS139.7x6.3", "AL7075 CHS193.7x8", heavy
    ],
    BCROSS: [
      "S460 CHS60.3x4", "S460 CHS76.1x4", "S460 CHS88.9x4",
      "S460 CHS114.3x4", "S460 CHS114.3x5", "S460 CHS139.7x5",
      "S460 CHS168.3x6.3", "S460 CHS193.7x8",
      "AL7075 CHS88.9x5", "AL7075 CHS114.3x5",
      "AL7075 CHS139.7x6.3", "AL7075 CHS193.7x8", heavy
    ]
  };

  const groups = Object.keys(options);
  const picks = {};
  for (const g of groups) picks[g] = heavy;

  function makeDesign() {
    return {
      note: "Twin full-depth pinned Pratt trusses with X-braced top, bottom and transverse planes; sections are sized by analysis.",
      nodes: nodes.map(n => ({ ...n })),
      joints: {},
      members: parts.map(p => ({
        a: p.a,
        b: p.b,
        spec: picks[p.group]
      }))
    };
  }

  function number(v) {
    const n = typeof v === "number" ? v : parseFloat(v);
    return Number.isFinite(n) ? n : null;
  }

  function massOf(r) {
    const m = r ? number(r.mass) : null;
    return m === null ? Infinity : m;
  }

  function passesMargins(r) {
    if (!r || r.error || !r.ok) return false;

    let u = number(r.maxUtil);
    if (u !== null) {
      if (u > 2) u /= 100;
      if (u > 0.68) return false;
    }

    const a = number(r.alphaCrMin);
    if (a !== null && a < 5.2) return false;

    const sag = number(r.sag), sagLimit = number(r.sagLimit);
    if (sag !== null && sagLimit !== null && sagLimit > 0 &&
        Math.abs(sag) > 0.85 * sagLimit) return false;

    const sway = number(r.sway), swayLimit = number(r.swayLimit);
    if (sway !== null && swayLimit !== null && swayLimit > 0 &&
        Math.abs(sway) > 0.85 * swayLimit) return false;

    const f = number(r.frequency), fMin = number(r.fMin);
    if (f !== null && fMin !== null && fMin > 0 && f < 1.10 * fMin) return false;

    const fatigue = number(r.fatigueWorst);
    if (fatigue !== null && fatigue <= 1.5 && fatigue > 0.84) return false;

    const rb = r.robustness;
    if (rb === false ||
        (rb && typeof rb === "object" &&
         (rb.ok === false || rb.pass === false))) return false;

    return true;
  }

  const cache = new Map();
  let calls = 0;
  const maxCalls = 280;
  let bestSafe = null;
  let bestNominal = null;

  function evaluate() {
    const key = groups.map(g => picks[g]).join("|");
    if (cache.has(key)) return cache.get(key);

    const d = makeDesign();
    let r;
    calls++;
    try {
      r = analyse(d);
    } catch (e) {
      r = { error: String(e) };
    }

    const item = { d, r, safe: passesMargins(r) };
    cache.set(key, item);

    if (r && r.ok && (!bestNominal || massOf(r) < massOf(bestNominal.r))) {
      bestNominal = item;
    }
    if (item.safe && (!bestSafe || massOf(r) < massOf(bestSafe.r))) {
      bestSafe = item;
    }
    return item;
  }

  evaluate();

  for (let round = 0; round < 3 && calls < maxCalls; round++) {
    const before = massOf(evaluate().r);

    for (const g of groups) {
      if (calls >= maxCalls) break;

      let chosenSpec = picks[g];
      let chosen = evaluate();

      for (const spec of options[g]) {
        if (calls >= maxCalls) break;
        picks[g] = spec;
        const test = evaluate();
        if (test.safe && massOf(test.r) < massOf(chosen.r)) {
          chosen = test;
          chosenSpec = spec;
        }
      }

      picks[g] = chosenSpec;
    }

    const after = massOf(evaluate().r);
    if (after >= before - 1e-6) break;
  }

  if (bestSafe) return bestSafe.d;
  if (bestNominal) return bestNominal.d;
  return evaluate().d;
}

function design(site, analyse) {
  const xs = [0, 4.914, 9.829, 14.743, 19.657, 24.571, 29.486, 34.4];
  const nodes = [];
  const parts = [];
  const add = (a, b, group) => parts.push({ a, b, group });
  const al = s => `AL7075 CHS${s}`;
  const st = s => `S460 CHS${s}`;
  const heavy = st("457x16");

  // Lower nodes sit halfway between the deck stations.
  for (let j = 0; j < 7; j++) {
    const x = (xs[j] + xs[j + 1]) / 2;
    nodes.push({ id: `BL${j}`, x, y: -4.70, z: -2.35, joint: "pin" });
    nodes.push({ id: `BR${j}`, x, y: -4.70, z:  2.35, joint: "pin" });
  }

  // Paired alternating-node Warren trusses.
  for (const [top, bottom] of [["L", "BL"], ["R", "BR"]]) {
    for (let i = 0; i < 7; i++) {
      const zone = (i === 0 || i === 6) ? 0 : (i === 1 || i === 5) ? 1 : 2;
      add(`${top}${i}`, `${top}${i + 1}`, `U${zone}`);
    }

    for (let j = 0; j < 6; j++) {
      const zone = (j === 0 || j === 5) ? 0 : (j === 1 || j === 4) ? 1 : 2;
      add(`${bottom}${j}`, `${bottom}${j + 1}`, `B${zone}`);
    }

    for (let i = 0; i < 8; i++) {
      if (i > 0) {
        const j = i - 1;
        const zone = (j === 0 || j === 6) ? 0 : (j === 1 || j === 5) ? 1 : 2;
        add(`${top}${i}`, `${bottom}${j}`, `D${zone}`);
      }
      if (i < 7) {
        const j = i;
        const zone = (j === 0 || j === 6) ? 0 : (j === 1 || j === 5) ? 1 : 2;
        add(`${top}${i}`, `${bottom}${j}`, `D${zone}`);
      }
    }
  }

  // Transverse ties and X bracing in both horizontal chord planes.
  for (let i = 0; i < 8; i++) add(`L${i}`, `R${i}`, "CT");
  for (let j = 0; j < 7; j++) add(`BL${j}`, `BR${j}`, "CB");

  for (let i = 0; i < 7; i++) {
    add(`L${i}`, `R${i + 1}`, "PT");
    add(`R${i}`, `L${i + 1}`, "PT");
  }
  for (let j = 0; j < 6; j++) {
    add(`BL${j}`, `BR${j + 1}`, "PB");
    add(`BR${j}`, `BL${j + 1}`, "PB");
  }

  // Transverse X frames tie the top and lower chord planes together.
  for (let i = 0; i < 8; i++) {
    const j = Math.min(i, 6);
    const group = (i === 0 || i === 7) ? "F0" : "F1";
    add(`L${i}`, `BR${j}`, group);
    add(`R${i}`, `BL${j}`, group);
  }

  const options = {
    U0: [al("88.9x5"), al("114.3x5"), al("168.3x6.3"), al("219.1x8"), al("273x10"),
         st("88.9x5"), st("114.3x5"), st("168.3x6.3"), st("273x10"), heavy],
    U1: [al("114.3x5"), al("168.3x6.3"), al("219.1x8"), al("273x10"), al("323.9x10"),
         st("114.3x5"), st("168.3x6.3"), st("219.1x8"), st("273x10"), heavy],
    U2: [al("168.3x6.3"), al("219.1x8"), al("273x10"), al("323.9x10"), al("406.4x12.5"),
         st("168.3x6.3"), st("219.1x8"), st("273x10"), st("323.9x10"), heavy],

    B0: [al("60.3x4"), al("88.9x5"), al("114.3x5"), al("168.3x6.3"), al("219.1x8"),
         st("76.1x4"), st("88.9x5"), st("114.3x5"), st("273x10"), heavy],
    B1: [al("88.9x5"), al("114.3x5"), al("168.3x6.3"), al("219.1x8"), al("273x10"),
         st("88.9x5"), st("114.3x5"), st("168.3x6.3"), st("273x10"), heavy],
    B2: [al("114.3x5"), al("168.3x6.3"), al("219.1x8"), al("273x10"), al("323.9x10"),
         st("114.3x5"), st("139.7x5"), st("168.3x6.3"), st("273x10"), heavy],

    D0: [al("114.3x5"), al("168.3x6.3"), al("219.1x8"), al("273x10"), al("323.9x10"),
         st("88.9x5"), st("114.3x5"), st("139.7x5"), st("168.3x6.3"), heavy],
    D1: [al("88.9x5"), al("114.3x5"), al("168.3x6.3"), al("219.1x8"), al("273x10"),
         st("76.1x4"), st("88.9x5"), st("114.3x5"), st("273x10"), heavy],
    D2: [al("60.3x4"), al("88.9x5"), al("114.3x5"), al("168.3x6.3"), al("219.1x8"),
         st("60.3x4"), st("88.9x5"), st("114.3x5"), st("139.7x5"), heavy],

    CT: [al("48.3x3.2"), al("60.3x4"), al("76.1x4"), al("88.9x5"), al("114.3x5"),
         st("48.3x3.2"), st("60.3x4"), st("76.1x4"), st("114.3x5"), heavy],
    CB: [al("48.3x3.2"), al("60.3x4"), al("76.1x4"), al("88.9x5"), al("114.3x5"),
         st("48.3x3.2"), st("60.3x4"), st("76.1x4"), st("114.3x5"), heavy],

    PT: [al("76.1x4"), al("88.9x5"), al("114.3x5"), al("168.3x6.3"), al("273x10"),
         st("76.1x4"), st("114.3x5"), st("168.3x6.3"), st("273x10"), heavy],
    PB: [al("76.1x4"), al("88.9x5"), al("114.3x5"), al("168.3x6.3"), al("273x10"),
         st("76.1x4"), st("114.3x5"), st("168.3x6.3"), st("273x10"), heavy],

    F0: [al("88.9x5"), al("114.3x5"), al("168.3x6.3"), al("219.1x8"), al("273x10"),
         st("88.9x5"), st("114.3x5"), st("168.3x6.3"), st("273x10"), heavy],
    F1: [al("88.9x5"), al("114.3x5"), al("168.3x6.3"), al("219.1x8"), al("273x10"),
         st("88.9x5"), st("114.3x5"), st("168.3x6.3"), st("273x10"), heavy]
  };

  const groupNames = Object.keys(options);
  const picks = {};
  for (const g of groupNames) picks[g] = heavy;

  function makeDesign() {
    return {
      note: "Paired full-depth alternating-node Warren trusses with crossed top and bottom planes and transverse X frames; sections are selected by analysis.",
      nodes: nodes.map(n => ({ ...n })),
      joints: {},
      members: parts.map(p => ({ a: p.a, b: p.b, spec: picks[p.group] }))
    };
  }

  function num(v) {
    const x = (typeof v === "number") ? v : parseFloat(v);
    return Number.isFinite(x) ? x : null;
  }

  function ratio(v) {
    let x = num(v);
    if (x !== null && x > 2) x /= 100;
    return x;
  }

  function passesMargins(r) {
    if (!r || r.error || !r.ok) return false;

    const u = ratio(r.maxUtil);
    if (u !== null && u > 0.58) return false;

    let acr = num(r.alphaCrMin);
    if (acr === null) acr = num(r.alphaCr);
    if (acr !== null && acr < 7.5) return false;

    const sag = num(r.sag), sagLimit = num(r.sagLimit);
    if (sag !== null && sagLimit !== null && sagLimit > 0 &&
        Math.abs(sag) > 0.82 * sagLimit) return false;

    const sway = num(r.sway), swayLimit = num(r.swayLimit);
    if (sway !== null && swayLimit !== null && swayLimit > 0 &&
        Math.abs(sway) > 0.82 * swayLimit) return false;

    const f = num(r.frequency), fMin = num(r.fMin);
    if (f !== null && fMin !== null && fMin > 0 && f < 1.12 * fMin) return false;

    const fatigue = ratio(r.fatigueWorst);
    if (fatigue !== null && fatigue > 0.78) return false;

    const rb = r.robustness;
    if (rb === false ||
        (rb && typeof rb === "object" && (rb.ok === false || rb.pass === false))) {
      return false;
    }
    return true;
  }

  function massOf(r) {
    const m = r ? num(r.mass) : null;
    return m === null ? Infinity : m;
  }

  const cache = new Map();
  let calls = 0;
  const maxCalls = 380;
  let bestSafe = null;
  let bestFeasible = null;

  function evaluate() {
    const key = groupNames.map(g => picks[g]).join("|");
    if (cache.has(key)) return cache.get(key);

    const d = makeDesign();
    let r;
    calls++;
    try {
      r = analyse(d);
    } catch (e) {
      r = { error: String(e) };
    }

    const item = { d, r, safe: passesMargins(r) };
    cache.set(key, item);

    if (r && r.ok && (!bestFeasible || massOf(r) < massOf(bestFeasible.r))) {
      bestFeasible = item;
    }
    if (item.safe && (!bestSafe || massOf(r) < massOf(bestSafe.r))) {
      bestSafe = item;
    }
    return item;
  }

  evaluate();

  for (let round = 0; round < 2 && calls < maxCalls; round++) {
    const before = massOf(evaluate().r);

    for (const g of groupNames) {
      if (calls >= maxCalls) break;

      let chosenSpec = picks[g];
      let chosen = evaluate();

      for (const spec of options[g]) {
        if (calls >= maxCalls) break;
        picks[g] = spec;
        const test = evaluate();
        if (test.safe && massOf(test.r) < massOf(chosen.r)) {
          chosen = test;
          chosenSpec = spec;
        }
      }
      picks[g] = chosenSpec;
    }

    const after = massOf(evaluate().r);
    if (after >= before - 1e-6) break;
  }

  if (bestSafe) return bestSafe.d;
  if (bestFeasible) return bestFeasible.d;
  return makeDesign();
}

function design(site, analyse) {
  const xs = [0, 4.914, 9.829, 14.743, 19.657, 24.571, 29.486, 34.4];
  const yB = -4.70;
  const nodes = [];
  const parts = [];
  const add = (a, b, group) => parts.push({ a, b, group });

  const chordZone = i =>
    (i === 0 || i === 6) ? 0 : (i === 1 || i === 5) ? 1 : 2;
  const webZone = i =>
    (i === 0 || i === 1 || i === 5 || i === 6) ? 0 : 1;

  for (let i = 0; i < 8; i++) {
    nodes.push({ id: `BL${i}`, x: xs[i], y: yB, z: -2.35, joint: "pin" });
    nodes.push({ id: `BR${i}`, x: xs[i], y: yB, z:  2.35, joint: "pin" });
  }

  for (const [top, bottom] of [["L", "BL"], ["R", "BR"]]) {
    for (let i = 0; i < 7; i++) {
      const z = chordZone(i);
      add(`${top}${i}`, `${top}${i + 1}`, `U${z}`);
      add(`${bottom}${i}`, `${bottom}${i + 1}`, `B${z}`);

      // Pratt diagonals slope toward the bridge centre.
      const d = webZone(i);
      if (i <= 3) add(`${top}${i}`, `${bottom}${i + 1}`, `D${d}`);
      else add(`${bottom}${i}`, `${top}${i + 1}`, `D${d}`);
    }

    for (let i = 0; i < 8; i++) add(`${top}${i}`, `${bottom}${i}`, "V");
  }

  // Transverse ties and one compression-capable diagonal per cross-frame.
  for (let i = 0; i < 8; i++) {
    add(`L${i}`, `R${i}`, "T");
    add(`BL${i}`, `BR${i}`, "T");
    if (i % 2 === 0) add(`L${i}`, `BR${i}`, "F");
    else add(`R${i}`, `BL${i}`, "F");
  }

  // Triangulate both longitudinal horizontal planes.
  for (let i = 0; i < 7; i++) {
    if (i % 2 === 0) {
      add(`L${i}`, `R${i + 1}`, "P");
      add(`BR${i}`, `BL${i + 1}`, "P");
    } else {
      add(`R${i}`, `L${i + 1}`, "P");
      add(`BL${i}`, `BR${i + 1}`, "P");
    }
  }

  const st = s => `S460 CHS${s}`;
  const al = s => `AL7075 CHS${s}`;
  const heavy = st("457x16");

  const options = {
    U0: [
      st("139.7x5"), st("193.7x8"), st("244.5x8"), st("273x10"),
      st("323.9x10"), st("406.4x12.5"), st("457x16"),
      al("193.7x8"), al("273x10"), al("323.9x10"), al("406.4x12.5")
    ],
    U1: [
      st("168.3x6.3"), st("219.1x8"), st("273x10"), st("323.9x10"),
      st("355.6x12.5"), st("406.4x12.5"), st("457x16"),
      al("219.1x8"), al("273x10"), al("323.9x10"),
      al("406.4x12.5"), al("457x16")
    ],
    U2: [
      st("193.7x8"), st("244.5x8"), st("273x10"), st("323.9x10"),
      st("355.6x12.5"), st("406.4x12.5"), st("457x16"),
      al("244.5x8"), al("273x10"), al("323.9x10"),
      al("406.4x12.5"), al("457x16")
