    const key = groups.map(function (g) { return ass[g]; }).join(",");
    if (cache.has(key)) return cache.get(key);
    if (calls >= MAX_CALLS) return null;
    calls++;
    let res;
    try {
      res = analyse(makeDesign(ass));
    } catch (e) {
