    if (!res || res.error || res.ok !== true) return false;
    if (res.maxUtil != null && res.maxUtil > 0.70) return false;
    if (res.alphaCr != null && res.alphaCr < 6.0) return false;
    if (res.sag != null && res.sagLimit != null && res.sag > 0.75 * res.sagLimit) return false;
    if (res.sway != null && res.swayLimit != null && res.sway > 0.75 * res.swayLimit) return false;
    if (res.frequency != null && res.fMin != null && res.frequency < 1.15 * res.fMin) return false;
    if (res.frequency != null && res.fMin == null && res.frequency < 2.2) return false;
    if (res.robustness === false) return false;
    return true;
  }

