  }

  let bestAss = Object.assign({}, cur);
  let bestRes = res0;
  let bestMass = (res0.mass != null) ? res0.mass : Infinity;

  const orders = [
    ["top", "bottom", "diag", "vert", "topCross", "botCross", "topHoriz", "botHoriz", "trans"],
    ["diag", "top", "bottom", "vert", "trans", "topHoriz", "botHoriz", "topCross", "botCross"],
    ["bottom", "diag", "top", "topCross", "trans", "vert", "botCross", "topHoriz", "botHoriz"]
  ];

  let round = 0;
  let improved = true;

  while (calls < 235 && round < 5 && improved) {
    improved = false;
    const order = orders[round % orders.length];

    for (let oi = 0; oi < order.length; oi++) {
      if (calls >= 235) break;
      const g = order[oi];
      const hiStart = cur[g];
      let lo = 0;
      let hi = hiStart;
      let bestIdx = hiStart;
      let foundSafe = false;

      while (lo <= hi) {
        if (calls >= 235) break;
