        }
      }
    }

    round++;
    const rr = check(cur);
    if (safe(rr)) {
      const m = (rr.mass != null) ? rr.mass : Infinity;
      if (m < bestMass) {
        bestMass = m;
        bestAss = Object.assign({}, cur);
        bestRes = rr;
      }
    } else {
      cur = Object.assign({}, bestAss);
    }
  }

  if (bestMass < Infinity && safe(bestRes)) {
    return makeDesign(bestAss);
  }
  return makeDesign(initial);
}

