    }

    if (!res || !isSafe(res, th)) {
      for (let i = 0; i < groups.length; i++) ass[groups[i]] = MAXIDX;
      res = evaluate(topo, H, ass, groups);
      if (!res || !isSafe(res, th)) return null;
    }

    let bestAss = {};
    for (let i = 0; i < groups.length; i++) {
      const g = groups[i];
      bestAss[g] = ass[g];
    }
    let bestRes = res;
    let bestMass = (res.mass != null) ? res.mass : Infinity;

    for (let p = 0; p < passes; p++) {
      if (calls >= MAX_CALLS - 3) break;
      const order = (p % 2 === 0) ? groups.slice() : groups.slice().reverse();

      for (let oi = 0; oi < order.length; oi++) {
        if (calls >= MAX_CALLS - 3) break;
        const g = order[oi];
        let lo = 0;
        let hi = ass[g];
        let bestIdx = ass[g];

        while (lo <= hi && calls < MAX_CALLS - 3) {
          const mid = (lo + hi) >> 1;
          const test = {};
          for (let i = 0; i < groups.length; i++) {
            const gg = groups[i];
            test[gg] = ass[gg];
          }
          test[g] = mid;
          const rr = evaluate(topo, H, test, groups);
          if (rr && isSafe(rr, th)) {
            bestIdx = mid;
            hi = mid - 1;
          } else {
            lo = mid + 1;
          }
        }

        if (bestIdx < ass[g]) {
          ass[g] = bestIdx;
          const rr = evaluate(topo, H, ass, groups);
          if (rr && isSafe(rr, th)) {
            const m = (rr.mass != null) ? rr.mass : Infinity;
            if (m < bestMass) {
              bestMass = m;
              bestRes = rr;
              bestAss = {};
              for (let i = 0; i < groups.length; i++) {
                const gg = groups[i];
                bestAss[gg] = ass[gg];
              }
            }
          }
        }
      }

      const rr = evaluate(topo, H, ass, groups);
      if (rr && isSafe(rr, th)) {
        const m = (rr.mass != null) ? rr.mass : Infinity;
        if (m < bestMass) {
          bestMass = m;
          bestRes = rr;
          bestAss = {};
          for (let i = 0; i < groups.length; i++) {
            const gg = groups[i];
            bestAss[gg] = ass[gg];
          }
        }
      }
    }

    return { topo: topo, H: H, ass: bestAss, res: bestRes, mass: bestMass };
  }

  const results = [];

  function run(topo, H, start, th, passes) {
    if (calls >= MAX_CALLS - 5) return null;
    const groups = (topo === "tri") ? triGroups :
                   (topo === "delta") ? deltaGroups :
                   (topo === "warren") ? warrenGroups : doubleGroups;
    const r = opt(topo, H, start, th, groups, passes);
    if (r && r.res && r.res.ok) {
      r.safeRob = isSafe(r.res, thRob);
      r.safeMod = isSafe(r.res, thMod);
      results.push(r);
    }
    return r;
  }

  // Main search: robust tri first, then moderate variants.
  run("tri", Hpar, triStart, thRob, 1);
  run("tri", Hpar, triStart, thMod, 1);
  run("tri", Hhyb, triStart, thMod, 1);
  run("double", Hpar, a3, thMod, 1);
  run("delta", Hflat, deltaStart, thMod, 1);
  run("warren", Hflat, warrenStart, thMod, 1);

  if (calls < MAX_CALLS - 60) {
    run("tri", Hflat, triStart, thMod, 1);
  }
  if (calls < MAX_CALLS - 50) {
    run("warren", Hhyb, warrenStart, thMod, 1);
  }
  if (calls < MAX_CALLS - 50) {
    run("delta", Hpar, deltaStart, thMod, 1);
  }

  const fallbackRes = evaluate("double", Hpar, a3, doubleGroups);
  const fallbackMass = (fallbackRes && fallbackRes.mass != null) ? fallbackRes.mass : 9430;

  let bestRob = null;
  let bestMod = null;
  for (let i = 0; i < results.length; i++) {
    const r = results[i];
    if (!r || !r.res || !r.res.ok) continue;
    if (r.safeRob && (!bestRob || r.mass < bestRob.mass)) bestRob = r;
    if (r.safeMod && (!bestMod || r.mass < bestMod.mass)) bestMod = r;
  }

  let chosen = null;

  if (bestRob && bestRob.mass < fallbackMass) {
    chosen = bestRob;
  } else if (bestMod && bestMod.mass < fallbackMass * 0.94) {
    chosen = bestMod;
  } else if (bestRob) {
    chosen = bestRob;
  } else if (bestMod && bestMod.mass < fallbackMass) {
    chosen = bestMod;
  }

  if (!chosen) {
    const out = buildDouble(Hpar, a3);
    out.note = "Fallback attempt-3 optimized S690 CHS double-Warren; no lighter robust candidate found.";
    return out;
  }

  let out;
  if (chosen.topo === "tri") out = buildTri(chosen.H, chosen.ass);
  else if (chosen.topo === "delta") out = buildDelta(chosen.H, chosen.ass);
  else if (chosen.topo === "warren") out = buildWarren(chosen.H, chosen.ass);
  else out = buildDouble(chosen.H, chosen.ass);

  out.note = "Optimized S690 CHS " + chosen.topo +
             " (H profile " + chosen.H.map(function (v) { return v.toFixed(2); }).join("/") +
             ", rough mass " + Math.round(chosen.mass) + " kg).";
  return out;
}

function design(site, analyse) {
  const L = 34.4, zL = -2.35, zR = 2.35;

  const CHS = [
    "CHS33.7x2.6", "CHS42.4x3.2", "CHS48.3x3.2", "CHS60.3x3.2",
    "CHS60.3x4", "CHS76.1x3.2", "CHS76.1x4", "CHS88.9x4",
    "CHS88.9x5", "CHS114.3x4", "CHS114.3x5", "CHS139.7x5",
    "CHS139.7x6.3", "CHS168.3x5", "CHS168.3x6.3", "CHS193.7x6.3",
    "CHS193.7x8", "CHS219.1x8", "CHS244.5x8", "CHS273x10",
    "CHS323.9x10", "CHS355.6x12.5", "CHS406.4x12.5", "CHS457x16"
  ];
  const MAXIDX = CHS.length - 1;

  const GROUPS = [
    "topE", "topM", "topC",
    "botE", "botM", "botC",
    "diagEnd", "diagNear", "diagMid", "diagCen",
    "vertE", "vertM",
    "topCross", "botCross",
    "topHoriz", "botHoriz", "trans"
  ];

  const PRIORITY = [
    "diagEnd", "diagNear", "topC", "topM", "botC", "botM",
    "topE", "botE", "diagMid", "diagCen", "vertE", "vertM",
    "topHoriz", "trans", "botHoriz", "topCross", "botCross"
  ];

  // Exact attempt-3 section assignment (nominal, S690 CHS).
  const exactAss = {
    topE: 14, topM: 14, topC: 14,
    botE: 14, botM: 12, botC: 12,
    diagEnd: 12, diagNear: 9, diagMid: 10, diagCen: 11,
    vertE: 1, vertM: 4,
    topCross: 3, botCross: 2,
    topHoriz: 11, botHoriz: 9, trans: 9
  };

  const allOpts = {
    topCrossMode: 1,
    botCrossMode: 1,
    topHorizMode: 1,
    botHorizMode: 1,
    transMode: 1
  };

  function cloneAss(a) {
    const o = {};
    for (let i = 0; i < GROUPS.length; i++) o[GROUPS[i]] = a[GROUPS[i]];
    return o;
  }
  function cloneSpecs(s) {
    const o = {};
    for (let i = 0; i < GROUPS.length; i++) o[GROUPS[i]] = s[GROUPS[i]];
    return o;
  }
  function mergeOpts(a, b) {
    const o = {};
    for (const k in a) o[k] = a[k];
    for (const k in b) o[k] = b[k];
    return o;
  }

  function makeHPar(nb, Hmax) {
    const H = [];
    for (let j = 0; j < nb; j++) {
      const t = (2 * j + 1) / (2 * nb);
      H[j] = Hmax * (1 - Math.pow(2 * t - 1, 2));
    }
    return H;
  }
  function makeHHyb(nb, Hmax, base) {
    const H = [];
    for (let j = 0; j < nb; j++) {
      const t = (2 * j + 1) / (2 * nb);
      H[j] = base + (Hmax - base) * (1 - Math.pow(2 * t - 1, 2));
    }
    return H;
  }

  const H14 = makeHPar(7, 4.75);
  const H28 = makeHPar(14, 4.75);
  const H28h = makeHHyb(14, 4.75, 1.2);

  function specsFromAss(ass) {
    const s = {};
    for (let i = 0; i < GROUPS.length; i++) {
      s[GROUPS[i]] = "S690 " + CHS[ass[GROUPS[i]]];
    }
    return s;
  }

  function classifyTop(k, m) {
    const d = Math.min(k, m - 1 - k);
    if (m === 14) {
      return d >= 5 ? "topC" : (d >= 2 ? "topM" : "topE");
    }
    const tc = Math.floor(m * 0.36);
    const tm = Math.floor(m * 0.14);
    return d >= tc ? "topC" : (d >= tm ? "topM" : "topE");
  }

  function classifyBottom(j, nseg) {
    const d = Math.min(j, nseg - 1 - j);
    if (nseg === 6) {
      return d >= 2 ? "botE" : (d >= 1 ? "botM" : "botC");
    }
    const te = Math.floor(nseg * 0.34);
    const tm = Math.floor(nseg * 0.17);
    return d >= te ? "botE" : (d >= tm ? "botM" : "botC");
  }

  function classifyDiag(j, nb) {
    const d = Math.min(j, nb - 1 - j);
    if (d === 0) return "diagEnd";
    if (d === 1) return "diagNear";
    if (d === 2) return "diagMid";
    return "diagCen";
  }

  function classifyVert(j, nb) {
    const mid = (nb - 1) / 2;
    const d = Math.abs(j - mid);
    const lim = nb === 7 ? 2 : Math.max(2, Math.floor(nb / 3));
    return d >= lim ? "vertE" : "vertM";
  }

  function matchMode(mode, idx) {
    if (mode === 1) return true;
    if (mode === 2) return idx % 2 === 0;
    if (mode === 3) return idx % 2 === 1;
    return false;
  }

  function activeGroups(m, opts) {
    const o = opts || {};
    const arr = [
      "topE", "topM", "topC",
      "botE", "botM", "botC",
      "diagEnd", "diagNear", "diagMid", "diagCen",
      "vertE", "vertM"
    ];
    if ((o.topCrossMode || 0) !== 0) arr.push("topCross");
    if ((o.botCrossMode || 0) !== 0) arr.push("botCross");
    if ((o.topHorizMode || 0) !== 0) arr.push("topHoriz");
    if ((o.botHorizMode || 0) !== 0 && m / 2 > 1) arr.push("botHoriz");
    if ((o.transMode || 0) !== 0) arr.push("trans");
    return arr;
  }

  function buildMulti(m, H, specs, opts) {
    const o = opts || {};
    const topCrossMode = o.topCrossMode == null ? 1 : o.topCrossMode;
    const botCrossMode = o.botCrossMode == null ? 1 : o.botCrossMode;
    const topHorizMode = o.topHorizMode == null ? 1 : o.topHorizMode;
    const botHorizMode = o.botHorizMode == null ? 1 : o.botHorizMode;
    const transMode = o.transMode == null ? 1 : o.transMode;

    const nb = m / 2;
    const step = m / 7;
    const s = L / m;
    const nodes = [];
    const members = [];

    function deckIndex(k) {
      if (step <= 0) return -1;
      if (k % step === 0) {
        const di = k / step;
        if (di >= 0 && di <= 7 && Math.abs(di - Math.round(di)) < 1e-9) return di;
      }
      return -1;
    }

    function topNode(side, k) {
      const di = deckIndex(k);
      if (di >= 0) return (side === "L" ? "L" : "R") + di;
      return (side === "L" ? "TL" : "TR") + k;
    }

    function add(a, b, g) {
      const sp = specs[g];
      if (sp) members.push([a, b, sp]);
    }

    for (let k = 0; k <= m; k++) {
      if (deckIndex(k) < 0) {
        const x = k * s;
        nodes.push({ id: "TL" + k, x: x, y: 0, z: zL });
        nodes.push({ id: "TR" + k, x: x, y: 0, z: zR });
      }
    }

    for (let j = 0; j < nb; j++) {
      const x = (2 * j + 1) * s;
      nodes.push({ id: "BL" + j, x: x, y: -H[j], z: zL });
      nodes.push({ id: "BR" + j, x: x, y: -H[j], z: zR });
    }

    // Top chord segments.
    for (let k = 0; k < m; k++) {
      const g = classifyTop(k, m);
      add(topNode("L", k), topNode("L", k + 1), g);
      add(topNode("R", k), topNode("R", k + 1), g);
    }

    // Bottom chord segments.
    const nseg = nb - 1;
    for (let j = 0; j < nseg; j++) {
      const g = classifyBottom(j, nseg);
      add("BL" + j, "BL" + (j + 1), g);
      add("BR" + j, "BR" + (j + 1), g);
    }

    // Vertical and diagonal web members.
    for (let j = 0; j < nb; j++) {
      const kmid = 2 * j + 1;
      const vg = classifyVert(j, nb);
      add("BL" + j, topNode("L", kmid), vg);
      add("BR" + j, topNode("R", kmid), vg);

      const dg = classifyDiag(j, nb);
      const k0 = 2 * j;
      const k1 = 2 * j + 2;
      add("BL" + j, topNode("L", k0), dg);
      add("BL" + j, topNode("L", k1), dg);
      add("BR" + j, topNode("R", k0), dg);
      add("BR" + j, topNode("R", k1), dg);
    }

    // Top cross-beams.
    for (let k = 0; k <= m; k++) {
      if (matchMode(topCrossMode, k)) {
        add(topNode("L", k), topNode("R", k), "topCross");
      }
    }

    // Bottom cross-beams.
    for (let j = 0; j < nb; j++) {
      if (matchMode(botCrossMode, j)) {
        add("BL" + j, "BR" + j, "botCross");
      }
    }

    // Top horizontal bracing.
    for (let k = 0; k < m; k++) {
      if (matchMode(topHorizMode, k)) {
        if (k % 2 === 0) {
          add(topNode("L", k), topNode("R", k + 1), "topHoriz");
        } else {
          add(topNode("R", k), topNode("L", k + 1), "topHoriz");
        }
      }
    }

    // Bottom horizontal bracing.
    for (let j = 0; j < nb - 1; j++) {
      if (matchMode(botHorizMode, j)) {
        if (j % 2 === 0) {
          add("BL" + j, "BR" + (j + 1), "botHoriz");
        } else {
          add("BR" + j, "BL" + (j + 1), "botHoriz");
        }
      }
    }

    // Transverse bracing.
    for (let j = 0; j < nb; j++) {
      if (matchMode(transMode, j)) {
        const k = 2 * j + 1;
        if (j % 2 === 0) {
          add("BL" + j, topNode("R", k), "trans");
        } else {
          add("BR" + j, topNode("L", k), "trans");
        }
      }
    }

    return { nodes: nodes, members: members };
  }

  const cache = new Map();
  let calls = 0;
  const MAX_CALLS = 392;

  function cacheKey(m, H, specs, opts) {
    return String(m) + "|" +
      H.map(function (v) { return v.toFixed(4); }).join(",") + "|" +
      [opts.topCrossMode, opts.botCrossMode, opts.topHorizMode,
       opts.botHorizMode, opts.transMode].join(",") + "|" +
      GROUPS.map(function (g) { return specs[g]; }).join(";");
  }

  function evaluateSpec(m, H, specs, opts) {
    const key = cacheKey(m, H, specs, opts);
    if (cache.has(key)) return cache.get(key);
    if (calls >= MAX_CALLS) return null;
    calls++;

    let d;
    try {
      d = buildMulti(m, H, specs, opts);
    } catch (e) {
      d = { nodes: [], members: [] };
    }

    let r;
    try {
      r = analyse(d);
    } catch (e) {
      r = { error: String(e) };
    }
    cache.set(key, r);
    return r;
  }

  function evaluateAss(m, H, ass, opts) {
    return evaluateSpec(m, H, specsFromAss(ass), opts);
  }

  const TH_ROB = {
    maxUtil: 0.685,
    alpha: 7.2,
    sagFrac: 0.88,
    swayFrac: 0.88,
    freq: 2.10,
    fatigue: 0.76
  };

  const TH_AGG = {
    maxUtil: 0.715,
    alpha: 6.0,
    sagFrac: 0.92,
    swayFrac: 0.92,
    freq: 2.02,
    fatigue: 0.80
  };

  function isSafe(res, th) {
    if (!res || res.error || res.ok !== true) return false;
    if (res.maxUtil == null || res.maxUtil > th.maxUtil) return false;
    if (res.alphaCr != null && res.alphaCr < th.alpha) return false;
    if (res.sag != null && res.sagLimit != null &&
        res.sag > th.sagFrac * res.sagLimit) return false;
    if (res.sway != null && res.swayLimit != null &&
        res.sway > th.swayFrac * res.swayLimit) return false;
    if (res.frequency != null && res.frequency < th.freq) return false;
    if (res.fatigueWorst != null && res.fatigueWorst > th.fatigue) return false;
    if (res.robustness === false) return false;
    return true;
  }

  let bestRob = null;
  let bestAgg = null;
  let fallbackCand = null;

  function candidateFrom(m, H, opts, specs, res) {
    return {
      m: m,
      H: H.slice(),
      opts: mergeOpts(allOpts, opts),
      specs: cloneSpecs(specs),
      res: res,
      mass: res.mass
    };
  }

  function consider(m, H, opts, specs, res) {
    if (!res || res.error || res.ok !== true || res.mass == null) return;
    if (isSafe(res, TH_ROB)) {
      if (!bestRob || res.mass < bestRob.mass) {
        bestRob = candidateFrom(m, H, opts, specs, res);
      }
    }
    if (isSafe(res, TH_AGG)) {
      if (!bestAgg || res.mass < bestAgg.mass) {
        bestAgg = candidateFrom(m, H, opts, specs, res);
      }
    }
  }

  function optimizeAss(m, H, startAss, opts, th, callLimit, passes) {
    if (calls >= callLimit - 2) return null;

    let ass = {};
    for (let i = 0; i < GROUPS.length; i++) {
      const g = GROUPS[i];
      ass[g] = startAss[g] == null ? 14 : startAss[g];
    }
    const act = activeGroups(m, opts);

    let res = evaluateAss(m, H, ass, opts);

    let step = 0;
    while ((!res || !isSafe(res, th)) && step < 10 && calls < callLimit) {
      for (let i = 0; i < act.length; i++) {
        const g = act[i];
        if (ass[g] < MAXIDX) ass[g]++;
      }
      res = evaluateAss(m, H, ass, opts);
      step++;

      let any = false;
      for (let i = 0; i < act.length; i++) {
        if (ass[act[i]] < MAXIDX) { any = true; break; }
      }
      if (!any) break;
    }

    if (!res || !isSafe(res, th)) {
      if (calls >= callLimit - 1) return null;
      for (let i = 0; i < act.length; i++) ass[act[i]] = MAXIDX;
      res = evaluateAss(m, H, ass, opts);
      if (!res || !isSafe(res, th)) return null;
    }

    let bestAss = cloneAss(ass);
    let bestRes = res;
    let bestMass = res.mass;

    for (let pass = 0; pass < passes; pass++) {
      if (calls >= callLimit - 2) break;

      let order;
      if (pass % 2 === 0) {
        order = [];
        for (let i = 0; i < PRIORITY.length; i++) {
          if (act.indexOf(PRIORITY[i]) >= 0) order.push(PRIORITY[i]);
        }
        for (let i = 0; i < act.length; i++) {
          if (order.indexOf(act[i]) < 0) order.push(act[i]);
        }
      } else {
        order = [];
        for (let i = 0; i < PRIORITY.length; i++) {
          if (act.indexOf(PRIORITY[i]) >= 0) order.push(PRIORITY[i]);
        }
        for (let i = 0; i < act.length; i++) {
          if (order.indexOf(act[i]) < 0) order.push(act[i]);
        }
        order.reverse();
      }

      for (let oi = 0; oi < order.length; oi++) {
        if (calls >= callLimit - 2) break;
        const g = order[oi];

        let lo = 0;
        let hi = ass[g];
        let best = ass[g];

        while (lo <= hi && calls < callLimit - 2) {
          const mid = (lo + hi) >> 1;
          const test = cloneAss(ass);
          test[g] = mid;
          const rr = evaluateAss(m, H, test, opts);
          if (rr && isSafe(rr, th)) {
            best = mid;
            hi = mid - 1;
          } else {
            lo = mid + 1;
          }
        }

        if (best < ass[g]) {
          ass[g] = best;
          const rr = evaluateAss(m, H, ass, opts);
          if (rr && isSafe(rr, th) && rr.mass < bestMass) {
            bestMass = rr.mass;
            bestAss = cloneAss(ass);
            bestRes = rr;
          }
        }
      }

      const rr = evaluateAss(m, H, ass, opts);
      if (rr && isSafe(rr, th) && rr.mass < bestMass) {
        bestMass = rr.mass;
        bestAss = cloneAss(ass);
        bestRes = rr;
      }
    }

    return {
      m: m,
      H: H.slice(),
      opts: mergeOpts(allOpts, opts),
      ass: bestAss,
      specs: specsFromAss(bestAss),
      res: bestRes,
      mass: bestMass
    };
  }

  function substituteAL(cand, th, callLimit) {
    if (!cand || !cand.specs) return cand;
    if (calls >= callLimit - 2) return cand;

    let specs = cloneSpecs(cand.specs);
    let cur = evaluateSpec(cand.m, cand.H, specs, cand.opts);
    if (!cur || !isSafe(cur, th)) return cand;

    const act = activeGroups(cand.m, cand.opts);
    const order = [
      "topHoriz", "trans", "botHoriz", "topCross", "botCross",
      "vertE", "vertM",
      "diagEnd", "diagNear", "diagMid", "diagCen",
      "botC", "botM", "botE",
      "topE", "topM", "topC"
    ];

    for (let oi = 0; oi < order.length; oi++) {
      if (calls >= callLimit - 2) break;
      const g = order[oi];
      if (act.indexOf(g) < 0) continue;
      if (!specs[g] || specs[g].indexOf("S690 ") !== 0) continue;

      let lo = 0;
      let hi = MAXIDX;
      let bestIdx = -1;
      let bestRes = null;

      while (lo <= hi && calls < callLimit - 2) {
        const mid = (lo + hi) >> 1;
        const test = cloneSpecs(specs);
        test[g] = "AL7075 " + CHS[mid];
        const rr = evaluateSpec(cand.m, cand.H, test, cand.opts);
        if (rr && isSafe(rr, th)) {
          bestIdx = mid;
          bestRes = rr;
          hi = mid - 1;
        } else {
          lo = mid + 1;
        }
      }

      if (bestIdx >= 0 && bestRes) {
        const test = cloneSpecs(specs);
        test[g] = "AL7075 " + CHS[bestIdx];
