  const exactSpecs = specsFromAss(exactAss);
  const exactRes = evaluateSpec(14, H14, exactSpecs, allOpts);
  if (exactRes && exactRes.ok) {
    fallbackCand = candidateFrom(14, H14, allOpts, exactSpecs, exactRes);
    consider(14, H14, allOpts, exactSpecs, exactRes);
  }

  // Cheap bracing-removal / thinning tests at the exact sections.
  const variants = [
    { opts: allOpts },
    { opts: mergeOpts(allOpts, { botHorizMode: 0 }) },
    { opts: mergeOpts(allOpts, { topHorizMode: 0 }) },
    { opts: mergeOpts(allOpts, { transMode: 0 }) },
    { opts: mergeOpts(allOpts, { topHorizMode: 0, botHorizMode: 0 }) },
    { opts: mergeOpts(allOpts, { topHorizMode: 2 }) },
    { opts: mergeOpts(allOpts, { botHorizMode: 2 }) },
    { opts: mergeOpts(allOpts, { transMode: 2 }) },
    { opts: mergeOpts(allOpts, { topCrossMode: 2 }) },
    { opts: mergeOpts(allOpts, { topCrossMode: 2, botHorizMode: 0 }) }
  ];

  let cheapBest = null;
  for (let vi = 0; vi < variants.length; vi++) {
    if (calls >= 30) break;
    const o = variants[vi].opts;
    const r = evaluateSpec(14, H14, exactSpecs, o);
    if (!r || !r.ok) continue;
    consider(14, H14, o, exactSpecs, r);
    if (isSafe(r, TH_ROB)) {
      if (!cheapBest || r.mass < cheapBest.mass) {
        cheapBest = candidateFrom(14, H14, o, exactSpecs, r);
      }
    }
  }

  // Optimize the original double-Warren topology.
  let baseCand = null;
  if (calls < 150) {
    const r = optimizeAss(14, H14, exactAss, allOpts, TH_ROB, 150, 2);
    if (r) {
      baseCand = r;
      consider(r.m, r.H, r.opts, r.specs, r.res);
    }
  }

  let bestNow = bestRob;
  if (baseCand && (!bestNow || baseCand.mass < bestNow.mass)) bestNow = baseCand;

  // Remove the bottom plan bracing; this is often redundant because the
  // cross-frames already triangulate each transverse section.
  const optsNoBot = mergeOpts(allOpts, { botHorizMode: 0 });
  let noBotCand = null;
  if (calls < 285) {
    const start = exactAss;
    const r = optimizeAss(14, H14, start, optsNoBot, TH_ROB, 285, 2);
    if (r) {
      noBotCand = r;
      consider(r.m, r.H, r.opts, r.specs, r.res);
    }
  }

  // Try a finer 28-panel variant: shorter chord buckling lengths, more web.
  let fineCand = null;
  if (calls < 345) {
    let start = exactAss;
    if (baseCand && baseCand.ass) start = baseCand.ass;
    const r = optimizeAss(28, H28, start, allOpts, TH_ROB, 345, 1);
    if (r) {
      fineCand = r;
      consider(r.m, r.H, r.opts, r.specs, r.res);
    }
