  // If there is still budget, try one more fine-profile variant.
  if (calls < 360) {
    const r2 = optimizeAss(28, H28h, exactAss, allOpts, TH_ROB, 360, 1);
    if (r2) {
      consider(r2.m, r2.H, r2.opts, r2.specs, r2.res);
    }
  }

