  if (!bestRob && cheapBest) bestRob = cheapBest;
  if (!bestRob && fallbackCand) bestRob = fallbackCand;

  // Substitute lighter aluminium CHS where the analysis confirms it is safe.
  if (bestRob && calls < MAX_CALLS - 2) {
    const alCand = substituteAL(bestRob, TH_ROB, MAX_CALLS - 1);
    if (alCand && alCand.mass < bestRob.mass) {
      bestRob = alCand;
      consider(alCand.m, alCand.H, alCand.opts, alCand.specs, alCand.res);
    }
  }

  // Choose a final design.  Prefer the robust candidate; allow the slightly
  // more aggressive candidate only if it is substantially lighter.
  let chosen = bestRob;
  if (bestAgg && chosen && bestAgg.mass < chosen.mass * 0.90) {
    chosen = bestAgg;
  }
  if (!chosen) chosen = fallbackCand;
  if (!chosen) {
    // Last-resort literal fallback: original attempt-3 sections.
    const out = buildMulti(14, H14, exactSpecs, allOpts);
    out.note = "Fallback S690 double-Warren with subdivided top chord and 3D bracing.";
    return out;
  }

  const out = buildMulti(chosen.m, chosen.H, chosen.specs, chosen.opts);
  out.note = "Robust optimized S690/AL space truss; search relaxed buckling/stiffness margins and tested bottom-bracing removal and finer panels.";
  return out;
}

