  }));
  variants.push(makeSkip(function (mb) {
    return mb.g === "TH_6";
  }));
  variants.push(makeSkip(function (mb) {
    return mb.g === "TCROSS" && mb.k != null && mb.k % 2 === 1;
  }));
  variants.push(makeSkip(function (mb) {
    return mb.g === "BCROSS" && mb.j != null && mb.j % 2 === 1;
  }));
  variants.push(makeSkip(function (mb) {
    return mb.g && mb.g.indexOf("TR_") === 0 && mb.j != null && mb.j % 2 === 1;
  }));

  let chosenSkip = null;
  let chosenRes = finalRes;

  for (let vi = 0; vi < variants.length; vi++) {
    if (calls >= MAX_CALLS - 2) break;
    const s = variants[vi];
    if (!s || s.size === 0) continue;
    const r = evalAss(finalAss, s);
    if (isSafe(r, TH_REM) && r.mass != null && r.mass < chosenRes.mass - 1) {
      chosenSkip = s;
      chosenRes = r;
    }
  }

  if (chosenSkip) {
    for (let vi = 0; vi < variants.length; vi++) {
      if (calls >= MAX_CALLS - 2) break;
      const s = variants[vi];
      if (!s || s.size === 0) continue;
      const u = new Set(chosenSkip);
      s.forEach(function (v) { u.add(v); });
      if (u.size === chosenSkip.size) continue;
      const r = evalAss(finalAss, u);
      if (isSafe(r, TH_REM) && r.mass != null && r.mass < chosenRes.mass - 1) {
        chosenSkip = u;
        chosenRes = r;
      }
    }
  }

  let finalSkip = null;
  if (chosenSkip && isSafe(chosenRes, TH_REM) && chosenRes.mass < finalRes.mass) {
    finalSkip = chosenSkip;
    finalRes = chosenRes;
  }

  if (!finalRes || !isSafe(finalRes, TH)) {
    finalAss = cloneAss(baseAss);
    finalSkip = null;
  }

  return buildDesign(finalAss, finalSkip);
}

