    CAND.push({ spec: "S690 " + nm, mass: A * 0.785 });
    CAND.push({ spec: "AL7075 " + nm, mass: A * 0.281 });
  }
  CAND.sort(function (a, b) { return a.mass - b.mass; });

  const idxOf = {};
  for (let i = 0; i < CAND.length; i++) idxOf[CAND[i].spec] = i;

  const TH = {
    maxUtil: 0.73,
    alpha: 6.5,
    sagFrac: 0.885,
    swayFrac: 0.90,
    freq: 2.20,
    fatigue: 0.73
  };

  function isSafe(r, th) {
    if (!r || r.error || r.ok !== true) return false;
    if (r.maxUtil == null || r.maxUtil > th.maxUtil) return false;
    if (r.alphaCr != null && r.alphaCr < th.alpha) return false;
    if (r.sag != null && r.sagLimit != null && r.sag > th.sagFrac * r.sagLimit) return false;
    if (r.sway != null && r.swayLimit != null && r.sway > th.swayFrac * r.swayLimit) return false;
    if (r.frequency != null && r.frequency < th.freq) return false;
    if (r.fatigueWorst != null && r.fatigueWorst > th.fatigue) return false;
    if (r.robustness === false) return false;
    return true;
  }

  // Common deck coordinates.
  function baseCoords() {
    const c = {};
    for (let i = 0; i <= 7; i++) {
      c["L" + i] = { x: deckX[i], y: 0, z: zL };
      c["R" + i] = { x: deckX[i], y: 0, z: zR };
    }
    return c;
  }

  // Double-Warren (attempt-6 topology), with optional top horizontal bracing.
  function makeDouble(ass, opts) {
    opts = opts || {};
    const m = 14, nb = 7, s = L / m;
    const H = [1.2602040816326523, 3.198979591836735, 4.362244897959184,
               4.75, 4.362244897959183, 3.198979591836735, 1.2602040816326523];
    const nodes = [], members = [], groups = [], lengths = [];
    const coords = baseCoords();

    for (let k = 1; k <= 13; k += 2) {
      const x = k * s;
      nodes.push({ id: "TL" + k, x: x, y: 0, z: zL });
      nodes.push({ id: "TR" + k, x: x, y: 0, z: zR });
      coords["TL" + k] = { x: x, y: 0, z: zL };
      coords["TR" + k] = { x: x, y: 0, z: zR };
    }
    for (let j = 0; j <= 6; j++) {
      const x = (2 * j + 1) * s;
      nodes.push({ id: "BL" + j, x: x, y: -H[j], z: zL });
      nodes.push({ id: "BR" + j, x: x, y: -H[j], z: zR });
      coords["BL" + j] = { x: x, y: -H[j], z: zL };
      coords["BR" + j] = { x: x, y: -H[j], z: zR };
    }

    function tn(side, k) {
      if (k % 2 === 0) return (side === "L" ? "L" : "R") + (k / 2);
      return (side === "L" ? "TL" : "TR") + k;
    }
    function add(a, b, g) {
      if (!ass[g]) return;
      const A = coords[a], B = coords[b];
      if (!A || !B) return;
      const dx = A.x - B.x, dy = A.y - B.y, dz = A.z - B.z;
      members.push([a, b, ass[g]]);
      groups.push(g);
      lengths.push(Math.sqrt(dx * dx + dy * dy + dz * dz));
    }

    for (let k = 0; k < m; k++) {
      const d = Math.min(k, m - 1 - k);
      add(tn("L", k), tn("L", k + 1), "TC_" + d);
      add(tn("R", k), tn("R", k + 1), "TC_" + d);
    }
    for (let j = 0; j < 6; j++) {
      const d = Math.min(j, 5 - j);
      add("BL" + j, "BL" + (j + 1), "BC_" + d);
      add("BR" + j, "BR" + (j + 1), "BC_" + d);
    }
    for (let j = 0; j <= 6; j++) {
      const d = Math.min(j, 6 - j);
      const k = 2 * j + 1;
      add("BL" + j, tn("L", k), "V_" + d);
      add("BR" + j, tn("R", k), "V_" + d);
      const k0 = 2 * j, k1 = 2 * j + 2;
      add("BL" + j, tn("L", k0), "SD_" + d);
      add("BL" + j, tn("L", k1), "SD_" + d);
      add("BR" + j, tn("R", k0), "SD_" + d);
      add("BR" + j, tn("R", k1), "SD_" + d);
    }
    for (let k = 0; k <= 14; k++) add(tn("L", k), tn("R", k), "TCROSS");
    for (let j = 0; j <= 6; j++) add("BL" + j, "BR" + j, "BCROSS");

    if (opts.useTH !== false) {
      for (let k = 0; k < 14; k++) {
        if (opts.halfTH && (k % 2 !== 0)) continue;
        const d = Math.min(k, 13 - k);
        if (k % 2 === 0) add(tn("L", k), tn("R", k + 1), "TH_" + d);
        else add(tn("R", k), tn("L", k + 1), "TH_" + d);
      }
    }
    if (opts.useTR !== false) {
      for (let j = 0; j <= 6; j++) {
        const d = Math.min(j, 6 - j);
        const k = 2 * j + 1;
        if (j % 2 === 0) add("BL" + j, tn("R", k), "TR_" + d);
        else add("BR" + j, tn("L", k), "TR_" + d);
      }
    }

    return {
      note: "Double-Warren space truss variant.",
      nodes: nodes,
      members: members,
      groups: groups,
      lengths: lengths
    };
  }

  // Central-bottom-chord triangular space truss variants.
  function makeCentral(ass, opts) {
    opts = opts || {};
    const m = 14, nb = 7, s = L / m;
    const H = [1.2602040816326523, 3.198979591836735, 4.362244897959184,
               4.75, 4.362244897959183, 3.198979591836735, 1.2602040816326523];
    const web = opts.web || 4;
    const nodes = [], members = [], groups = [], lengths = [];
    const coords = baseCoords();

    for (let k = 1; k <= 13; k += 2) {
      const x = k * s;
      nodes.push({ id: "TL" + k, x: x, y: 0, z: zL });
      nodes.push({ id: "TR" + k, x: x, y: 0, z: zR });
      coords["TL" + k] = { x: x, y: 0, z: zL };
      coords["TR" + k] = { x: x, y: 0, z: zR };
    }
    for (let j = 0; j <= 6; j++) {
      const x = (2 * j + 1) * s;
      nodes.push({ id: "C" + j, x: x, y: -H[j], z: 0 });
      coords["C" + j] = { x: x, y: -H[j], z: 0 };
    }

    function tn(side, k) {
      if (k % 2 === 0) return (side === "L" ? "L" : "R") + (k / 2);
      return (side === "L" ? "TL" : "TR") + k;
    }
    function add(a, b, g) {
      if (!ass[g]) return;
      const A = coords[a], B = coords[b];
      if (!A || !B) return;
      const dx = A.x - B.x, dy = A.y - B.y, dz = A.z - B.z;
      members.push([a, b, ass[g]]);
      groups.push(g);
      lengths.push(Math.sqrt(dx * dx + dy * dy + dz * dz));
    }

    for (let k = 0; k < m; k++) {
      const d = Math.min(k, m - 1 - k);
      add(tn("L", k), tn("L", k + 1), "TC_" + d);
      add(tn("R", k), tn("R", k + 1), "TC_" + d);
    }
    for (let j = 0; j < 6; j++) {
      const d = Math.min(j, 5 - j);
      add("C" + j, "C" + (j + 1), "BC_" + d);
    }
    for (let j = 0; j <= 6; j++) {
      const d = Math.min(j, 6 - j);
      const k0 = 2 * j, k1 = 2 * j + 2;
      add("C" + j, tn("L", k0), "CW_" + d);
      add("C" + j, tn("R", k0), "CW_" + d);
      add("C" + j, tn("L", k1), "CW_" + d);
      add("C" + j, tn("R", k1), "CW_" + d);
      if (web === 6) {
        const km = 2 * j + 1;
        add("C" + j, tn("L", km), "CWM_" + d);
        add("C" + j, tn("R", km), "CWM_" + d);
      }
    }
    for (let k = 0; k <= 14; k++) add(tn("L", k), tn("R", k), "TCROSS");

    if (opts.useTH) {
      for (let k = 0; k < 14; k++) {
        const d = Math.min(k, 13 - k);
        if (k % 2 === 0) add(tn("L", k), tn("R", k + 1), "TH_" + d);
        else add(tn("R", k), tn("L", k + 1), "TH_" + d);
      }
    }

    return {
      note: "Central-bottom-chord triangular space truss.",
      nodes: nodes,
      members: members,
      groups: groups,
      lengths: lengths
    };
  }

  // Group lists.
  const D_GROUPS = [];
  for (let d = 0; d <= 6; d++) D_GROUPS.push("TC_" + d);
  for (let d = 0; d <= 2; d++) D_GROUPS.push("BC_" + d);
  for (let d = 0; d <= 3; d++) { D_GROUPS.push("V_" + d); D_GROUPS.push("SD_" + d); }
  D_GROUPS.push("TCROSS", "BCROSS");
  for (let d = 0; d <= 6; d++) D_GROUPS.push("TH_" + d);
  for (let d = 0; d <= 3; d++) D_GROUPS.push("TR_" + d);

  const C_GROUPS = [];
  for (let d = 0; d <= 6; d++) C_GROUPS.push("TC_" + d);
  for (let d = 0; d <= 2; d++) C_GROUPS.push("BC_" + d);
  for (let d = 0; d <= 3; d++) { C_GROUPS.push("CW_" + d); C_GROUPS.push("CWM_" + d); }
  C_GROUPS.push("TCROSS");
  for (let d = 0; d <= 6; d++) C_GROUPS.push("TH_" + d);

  // Exact attempt-6 section assignment (known safe fallback).
  const D_ASS = {};
  D_ASS["TC_0"] = "S690 CHS168.3x6.3";
  D_ASS["TC_1"] = "S690 CHS168.3x6.3";
  D_ASS["TC_2"] = "S690 CHS168.3x6.3";
  D_ASS["TC_3"] = "AL7075 CHS273x10";
  D_ASS["TC_4"] = "S690 CHS168.3x6.3";
  D_ASS["TC_5"] = "S690 CHS168.3x6.3";
  D_ASS["TC_6"] = "S690 CHS168.3x6.3";
  D_ASS["BC_0"] = "S690 CHS168.3x5";
  D_ASS["BC_1"] = "S690 CHS139.7x6.3";
  D_ASS["BC_2"] = "S690 CHS168.3x6.3";
  D_ASS["V_0"] = "AL7075 CHS33.7x2.6";
  D_ASS["V_1"] = "AL7075 CHS60.3x3.2";
  D_ASS["V_2"] = "S690 CHS60.3x3.2";
  D_ASS["V_3"] = "S690 CHS60.3x4";
  D_ASS["SD_0"] = "S690 CHS168.3x5";
  D_ASS["SD_1"] = "AL7075 CHS139.7x5";
  D_ASS["SD_2"] = "AL7075 CHS168.3x6.3";
  D_ASS["SD_3"] = "S690 CHS139.7x5";
  D_ASS["TCROSS"] = "AL7075 CHS76.1x4";
  D_ASS["BCROSS"] = "AL7075 CHS60.3x3.2";
  D_ASS["TH_0"] = "AL7075 CHS193.7x8";
  D_ASS["TH_1"] = "AL7075 CHS193.7x8";
  D_ASS["TH_2"] = "AL7075 CHS193.7x6.3";
  D_ASS["TH_3"] = "AL7075 CHS168.3x6.3";
  D_ASS["TH_4"] = "S690 CHS114.3x4";
  D_ASS["TH_5"] = "AL7075 CHS139.7x5";
  D_ASS["TH_6"] = "S690 CHS88.9x4";
  D_ASS["TR_0"] = "AL7075 CHS60.3x4";
  D_ASS["TR_1"] = "AL7075 CHS76.1x4";
  D_ASS["TR_2"] = "AL7075 CHS114.3x4";
  D_ASS["TR_3"] = "AL7075 CHS88.9x5";

  // Heavy double topology for no-top-bracing trials.
  const D_HEAVY = {};
  for (let i = 0; i < D_GROUPS.length; i++) D_HEAVY[D_GROUPS[i]] = "S690 CHS219.1x8";

  // Medium and heavy central starts.
  const C_MED = {};
  for (let d = 0; d <= 6; d++) C_MED["TC_" + d] = D_ASS["TC_" + d];
  C_MED["BC_0"] = "S690 CHS193.7x8";
  C_MED["BC_1"] = "S690 CHS219.1x8";
  C_MED["BC_2"] = "S690 CHS273x10";
  C_MED["CW_0"] = "S690 CHS168.3x5";
  C_MED["CW_1"] = "AL7075 CHS139.7x5";
  C_MED["CW_2"] = "AL7075 CHS168.3x6.3";
  C_MED["CW_3"] = "S690 CHS139.7x5";
  for (let d = 0; d <= 3; d++) C_MED["CWM_" + d] = "AL7075 CHS60.3x4";
  C_MED["TCROSS"] = "AL7075 CHS88.9x4";
  for (let d = 0; d <= 6; d++) C_MED["TH_" + d] = "AL7075 CHS139.7x5";

  const C_HEAVY = {};
  for (let d = 0; d <= 6; d++) C_HEAVY["TC_" + d] = "S690 CHS219.1x8";
  C_HEAVY["BC_0"] = "S690 CHS273x10";
  C_HEAVY["BC_1"] = "S690 CHS273x10";
  C_HEAVY["BC_2"] = "S690 CHS273x10";
  for (let d = 0; d <= 3; d++) {
    C_HEAVY["CW_" + d] = "S690 CHS168.3x6.3";
    C_HEAVY["CWM_" + d] = "S690 CHS139.7x6.3";
  }
  C_HEAVY["TCROSS"] = "S690 CHS114.3x5";
  for (let d = 0; d <= 6; d++) C_HEAVY["TH_" + d] = "AL7075 CHS193.7x8";

  let calls = 0;
  const MAX_CALLS = 395;
  const cache = new Map();

  function evalDesign(name, makeFn, ass, opts, groupList) {
    opts = opts || {};
    const optKey = JSON.stringify(opts);
    let sig = name + "|" + optKey + "|";
    for (let i = 0; i < groupList.length; i++) sig += (ass[groupList[i]] || "") + ";";
    if (cache.has(sig)) return cache.get(sig);
    if (calls >= MAX_CALLS) return null;
    calls++;
    let d;
    try {
      d = makeFn(ass, opts);
    } catch (e) {
      d = { nodes: [], members: [] };
    }
    const designObj = { note: d.note, nodes: d.nodes, members: d.members };
    let r;
    try {
      r = analyse(designObj);
    } catch (e) {
      r = { error: String(e) };
    }
    cache.set(sig, r);
    return r;
  }

  function evalD(ass, opts) { return evalDesign("D", makeDouble, ass, opts || {}, D_GROUPS); }
  function evalC(ass, opts) { return evalDesign("C", makeCentral, ass, opts || {}, C_GROUPS); }

  function clone(o) {
    const r = {};
    for (const k in o) r[k] = o[k];
    return r;
  }

  function optimize(evalFn, makeFn, assStart, opts, groupList, th, maxCalls, passes) {
    let ass = clone(assStart);
    let res = evalFn(ass, opts);
    if (!isSafe(res, th)) return null;

    let bestAss = clone(ass);
    let bestRes = res;
    let bestMass = res.mass;
    const start = calls;

    let built = makeFn(ass, opts);
    const active = [];
    const seen = {};
    for (let i = 0; i < built.groups.length; i++) {
      const g = built.groups[i];
      if (!seen[g]) {
        seen[g] = true;
        active.push(g);
      }
    }

    function groupMass(g) {
      let sum = 0;
      const idx = idxOf[ass[g]];
      const rate = (idx != null) ? CAND[idx].mass : 1;
      for (let i = 0; i < built.members.length; i++) {
        if (built.groups[i] === g) sum += rate * built.lengths[i];
      }
      return sum;
    }

    for (let pass = 0; pass < passes; pass++) {
      if (calls - start >= maxCalls) break;
      const order = active.slice();
      order.sort(function (a, b) { return groupMass(b) - groupMass(a); });

      for (let oi = 0; oi < order.length; oi++) {
        if (calls - start >= maxCalls) break;
        const g = order[oi];
        if (!ass[g]) continue;
        const curIdx = idxOf[ass[g]];
        if (curIdx == null || curIdx <= 0) continue;

        let lo = 0, hi = curIdx - 1, bestIdx = curIdx;
        while (lo <= hi && calls - start < maxCalls) {
          const mid = (lo + hi) >> 1;
          const test = clone(ass);
          test[g] = CAND[mid].spec;
          const rr = evalFn(test, opts);
          if (isSafe(rr, th)) {
            bestIdx = mid;
            hi = mid - 1;
          } else {
            lo = mid + 1;
          }
        }

        let chosen = bestIdx;
        for (let j = bestIdx - 1; j >= Math.max(0, bestIdx - 3); j--) {
          if (calls - start >= maxCalls) break;
          const test = clone(ass);
          test[g] = CAND[j].spec;
          const rr = evalFn(test, opts);
          if (isSafe(rr, th)) chosen = j;
        }

        if (chosen < curIdx) {
          const old = ass[g];
          ass[g] = CAND[chosen].spec;
          const rr = evalFn(ass, opts);
          if (isSafe(rr, th)) {
            if (rr.mass < bestMass - 1e-6) {
              bestMass = rr.mass;
              bestAss = clone(ass);
              bestRes = rr;
            }
            built = makeFn(ass, opts);
          } else {
            ass[g] = old;
          }
        }
      }

      const rr = evalFn(ass, opts);
      if (isSafe(rr, th) && rr.mass < bestMass - 1e-6) {
        bestMass = rr.mass;
        bestAss = clone(ass);
        bestRes = rr;
      }
    }

    return { ass: bestAss, opts: opts, res: bestRes, mass: bestMass };
  }

  // Base fallback design.
  const baseBuilt = makeDouble(D_ASS, {});
  const baseRes = evalD(D_ASS, {});
  let bestDouble = {
    mass: baseRes && baseRes.mass != null ? baseRes.mass : 1e9,
    nodes: baseBuilt.nodes,
    members: baseBuilt.members,
    name: "attempt-6 fallback"
  };
  let bestCentral = null;

  function considerDouble(name, built, res) {
    if (!res || res.ok !== true || !isSafe(res, TH)) return;
    if (res.mass != null && res.mass < bestDouble.mass - 1e-6) {
      bestDouble = { mass: res.mass, nodes: built.nodes, members: built.members, name: name };
    }
  }
  function considerCentral(name, built, res) {
    if (!res || res.ok !== true || !isSafe(res, TH)) return;
    if (res.mass != null && (!bestCentral || res.mass < bestCentral.mass - 1e-6)) {
      bestCentral = { mass: res.mass, nodes: built.nodes, members: built.members, name: name };
    }
  }

  considerDouble("base", baseBuilt, baseRes);

  // Try the double-Warren without top plan bracing.
  function runDoubleNoTH(budget) {
    const opts = { useTH: false };
    const probe = evalD(D_ASS, opts);
    let startAss;
    if (isSafe(probe, TH)) {
      considerDouble("double-noTH", makeDouble(D_ASS, opts), probe);
      startAss = D_ASS;
    } else {
      startAss = D_HEAVY;
    }
    const opt = optimize(evalD, makeDouble, startAss, opts, D_GROUPS, TH, budget, 1);
    if (opt) {
      const built = makeDouble(opt.ass, opt.opts);
      considerDouble("double-noTH-opt", built, opt.res);
    }
  }

  // Try central triangular truss variants.
  function runCentral(opts, budget) {
    const probe = evalC(C_MED, opts);
    let startAss;
    if (isSafe(probe, TH)) {
      considerCentral("central-med", makeCentral(C_MED, opts), probe);
      startAss = C_MED;
    } else {
      startAss = C_HEAVY;
    }
    const opt = optimize(evalC, makeCentral, startAss, opts, C_GROUPS, TH, budget, 1);
    if (opt) {
      const built = makeCentral(opt.ass, opt.opts);
      considerCentral("central-opt", built, opt.res);
    }
  }

  // Budgeted searches.
  if (calls < MAX_CALLS - 5) runDoubleNoTH(75);
  if (calls < MAX_CALLS - 5) runCentral({ web: 4, useTH: false }, 115);
  if (calls < MAX_CALLS - 5) runCentral({ web: 6, useTH: false }, 65);
  if (calls < MAX_CALLS - 5) runCentral({ web: 4, useTH: true }, 50);

  // Finally optimize the known-safe double-Warren sections with the remaining budget.
  const rem = MAX_CALLS - calls - 2;
  if (rem > 10) {
    const opt = optimize(evalD, makeDouble, D_ASS, {}, D_GROUPS, TH, rem, 1);
    if (opt) {
      const built = makeDouble(opt.ass, opt.opts);
      considerDouble("double-opt", built, opt.res);
    }
  }

  // Prefer the known-good double-Warren unless the central truss is clearly lighter.
  let final = bestDouble;
  if (bestCentral && bestCentral.mass < bestDouble.mass * 0.93) {
    final = bestCentral;
  }
  if (!final) final = { nodes: baseBuilt.nodes, members: baseBuilt.members, name: "fallback" };

  return {
    note: "Attempt 7: central-bottom triangular space truss and no-top-bracing double-Warren trials, with section search and conservative fallback.",
    nodes: final.nodes,
    members: final.members
  };
}

function design(site, analyse) {
