    for (let i = 0; i <= 6; i++) {
      add("BL" + i, "L" + i, dgGroup(i, 0));
      add("BL" + i, "L" + (i + 1), dgGroup(i, 1));
      add("BR" + i, "R" + i, dgGroup(i, 0));
      add("BR" + i, "R" + (i + 1), dgGroup(i, 1));
