        const g = "TH_" + d;
        if (opts.th === "x") {
          add("L" + i, "R" + (i + 1), g);
          add("R" + i, "L" + (i + 1), g);
        } else if (opts.th === "half") {
          if (i % 2 === 0) {
            add("L" + i, "R" + (i + 1), g);
          }
        } else {
          if (i % 2 === 0) add("L" + i, "R" + (i + 1), g);
          else add("R" + i, "L" + (i + 1), g);
