    }
    if (opts.useTB) {
      for (let i = 0; i <= 6; i++) {
        const d = Math.min(i, 6 - i);
        const g = "TB_" + d;
        if (i % 2 === 0) add("BL" + i, "R" + (i + 1), g);
        else add("BR" + i, "L" + i, g);
