    }
    if (opts.useBH) {
      for (let i = 0; i <= 5; i++) {
        const d = Math.min(i, 5 - i);
        const g = "BH_" + d;
        if (i % 2 === 0) add("BL" + i, "BR" + (i + 1), g);
        else add("BR" + i, "BL" + (i + 1), g);
      }
