  function runSimple(ass, opts) {
    const b = buildSimple(ass, opts);
    return ev({ note: b.note, nodes: b.nodes, members: b.members });
  }

  function makeAss(mode) {
    const a = {};
    const heavy = mode === "heavy";
    for (let d = 0; d <= 3; d++) {
      a["TC_" + d] = heavy ? "S690 CHS219.1x8" : "S690 CHS168.3x6.3";
    }
    if (!heavy) {
      a["TC_3"] = "S690 CHS193.7x8";
      a["BC_0"] = "S690 CHS168.3x5";
      a["BC_1"] = "S690 CHS139.7x6.3";
      a["BC_2"] = "S690 CHS168.3x6.3";
    } else {
      a["BC_0"] = "S690 CHS219.1x8";
      a["BC_1"] = "S690 CHS219.1x8";
      a["BC_2"] = "S690 CHS219.1x8";
    }
    for (let i = 0; i <= 6; i++) {
      const d = Math.min(i, 6 - i);
      let spec;
      if (heavy) {
        spec = "S690 CHS168.3x6.3";
      } else if (d === 0) {
        spec = "S690 CHS168.3x5";
      } else if (d === 1) {
        spec = "AL7075 CHS139.7x5";
      } else if (d === 2) {
        spec = "AL7075 CHS168.3x6.3";
      } else {
        spec = "S690 CHS139.7x5";
      }
      a[dgGroup(i, 0)] = spec;
      a[dgGroup(i, 1)] = spec;
    }
    for (let d = 0; d <= 3; d++) {
      a["TCROSS_" + d] = heavy ? "S690 CHS114.3x5" : "AL7075 CHS76.1x4";
      a["BCROSS_" + d] = heavy ? "S690 CHS88.9x5" : "AL7075 CHS60.3x3.2";
      a["TB_" + d] = heavy ? "S690 CHS114.3x5" : "AL7075 CHS114.3x5";
    }
