    a["TH_1"] = heavy ? "S690 CHS168.3x6.3" : "AL7075 CHS168.3x6.3";
    a["TH_2"] = heavy ? "S690 CHS168.3x6.3" : "AL7075 CHS139.7x5";
    a["TH_3"] = heavy ? "S690 CHS168.3x6.3" : "S690 CHS114.3x4";
