  function optimizeSimple(startAss, opts, budget) {
    const startCalls = calls;
    let ass = clone(startAss);
    let res = runSimple(ass, opts);
    if (!safe(res, TH_MAIN)) return null;
    let bestMass = res.mass;
    let bestAss = clone(ass);
    let bestRes = res;
    let bestBuilt = buildSimple(bestAss, opts);
    let built = buildSimple(ass, opts);

    const active = [];
    const seen = {};
    for (let i = 0; i < built.groups.length; i++) {
      const g = built.groups[i];
      if (!seen[g]) { seen[g] = true; active.push(g); }
    }

    function refreshBuilt() {
      built = buildSimple(ass, opts);
    }
    function groupMass(g) {
      let sum = 0;
      const rate = massMap[ass[g]] || 1;
      for (let i = 0; i < built.groups.length; i++) {
        if (built.groups[i] === g) sum += rate * built.lengths[i];
      }
      return sum;
    }

    for (let pass = 0; pass < 2; pass++) {
      if (calls - startCalls >= budget - 1) break;
      const order = active.slice();
      order.sort(function (a, b) { return groupMass(b) - groupMass(a); });

      for (let oi = 0; oi < order.length; oi++) {
        if (calls - startCalls >= budget - 1) break;
        const g = order[oi];
        const curSpec = ass[g];
        const curIdx = idxOf[curSpec];
        if (curIdx == null || curIdx <= 0) continue;

        let lo = 0, hi = curIdx - 1, bestIdx = curIdx;
        while (lo <= hi && calls - startCalls < budget - 1) {
          const mid = (lo + hi) >> 1;
          const test = clone(ass);
          test[g] = CAND[mid].spec;
          const rr = runSimple(test, opts);
          if (safe(rr, TH_MAIN)) {
            bestIdx = mid;
            hi = mid - 1;
          } else {
            lo = mid + 1;
          }
        }

        let chosen = bestIdx;
        for (let j = bestIdx - 1; j >= Math.max(0, bestIdx - 3); j--) {
          if (calls - startCalls >= budget - 1) break;
          const test = clone(ass);
          test[g] = CAND[j].spec;
          const rr = runSimple(test, opts);
          if (safe(rr, TH_MAIN)) chosen = j;
        }

        if (chosen < curIdx) {
          const old = ass[g];
          ass[g] = CAND[chosen].spec;
          const rr = runSimple(ass, opts);
          if (safe(rr, TH_MAIN)) {
            refreshBuilt();
            if (rr.mass < bestMass - 1e-6) {
              bestMass = rr.mass;
              bestAss = clone(ass);
              bestRes = rr;
              bestBuilt = buildSimple(bestAss, opts);
