          }
        }
      }

      const rr = runSimple(ass, opts);
      if (safe(rr, TH_MAIN) && rr.mass < bestMass - 1e-6) {
        bestMass = rr.mass;
        bestAss = clone(ass);
        bestRes = rr;
        bestBuilt = buildSimple(bestAss, opts);
      }
    }

    return { ass: bestAss, opts: opts, res: bestRes, mass: bestMass, built: bestBuilt };
  }

  const assM = makeAss("medium");
  const assH = makeAss("heavy");
  let bestSimple = null;

  function tryOptimize(opts, startAss, budget) {
    if (calls >= MAXCALLS - 2 || budget <= 0) return null;
    let res = runSimple(startAss, opts);
    let base = startAss;
    if (!safe(res, TH_MAIN)) {
      res = runSimple(assH, opts);
      if (!safe(res, TH_MAIN)) return null;
      base = assH;
    }
    return optimizeSimple(base, opts, Math.min(budget, MAXCALLS - calls - 1));
  }

  const optA = tryOptimize(
    { th: "single", useTB: true, useBH: false },
    assM,
    Math.min(250, MAXCALLS - calls - 80)
  );
  if (optA) bestSimple = optA;

  if (!bestSimple) {
    const optX = tryOptimize(
      { th: "x", useTB: true, useBH: true },
      assH,
      Math.min(300, MAXCALLS - calls - 5)
    );
    if (optX) bestSimple = optX;
  }

  function considerOpt(opts, startOpt, budget) {
    if (calls >= MAXCALLS - 5 || !startOpt) return;
    const startAss = startOpt.ass;
    const r0 = runSimple(startAss, opts);
    if (!safe(r0, TH_MAIN)) return;
    const opt = optimizeSimple(startAss, opts, Math.min(budget, MAXCALLS - calls - 1));
    if (opt && (!bestSimple || opt.mass < bestSimple.mass)) bestSimple = opt;
  }

  if (bestSimple) {
    considerOpt({ th: "single", useTB: false, useBH: false }, bestSimple, 60);
    considerOpt({ th: "half", useTB: true, useBH: false }, bestSimple, 55);
    considerOpt({ th: "half", useTB: false, useBH: false }, bestSimple, 45);
  }

  let finalDesign = null;
  let finalRes = null;

  if (bestSimple && bestSimple.res && safe(bestSimple.res, TH_MAIN) &&
      doubleBest && bestSimple.mass < doubleBest.mass - 20) {
    const r = bestSimple.res;
    let use = true;
    if (r.maxUtil != null && r.maxUtil > 0.725) use = false;
    if (r.alphaCr != null && r.alphaCr < 6.5) use = false;
    if (r.sag != null && r.sagLimit != null && r.sag > 0.89 * r.sagLimit) use = false;
    if (r.frequency != null && r.frequency < 2.15) use = false;
    if (bestSimple.mass > doubleBest.mass * 0.985) {
      if (r.maxUtil != null && r.maxUtil > 0.705) use = false;
      if (r.sag != null && r.sagLimit != null && r.sag > 0.875 * r.sagLimit) use = false;
    }
    if (use) {
      finalDesign = {
        nodes: bestSimple.built.nodes,
        members: bestSimple.built.members
      };
      finalRes = bestSimple.res;
    }
  }

  if (!finalDesign) {
    finalDesign = doubleBest ? doubleBest.design : doubleDesign;
    finalRes = doubleBest ? doubleBest.res : doubleRes;
  }

  // Last-resort fallback if every evaluation was exhausted.
  if (!finalDesign) finalDesign = doubleDesign;

  return {
    note: "Final attempt: simple full-height Warren space truss with transverse bracing, section-searched against the known-safe double-Warren fallback.",
    nodes: finalDesign.nodes,
    members: finalDesign.members
  };
}

function design(site, analyse) {
  // Box truss below the deck: two Warren side trusses (top chord = deck edge),
  // transverse rungs, top and bottom X-bracing, and a cross-diagonal per station.
  // Two topologies are sized iteratively with analyse(): B = deck stations only,
  // A = extra mid-panel top nodes (halves the compression chord buckling length).
  const XS = [0, 4.914, 9.829, 14.743, 19.657, 24.571, 29.486, 34.4];
  const ZL = -2.35, ZR = 2.35, HB = -4.7;

  // CHS ladder by ascending area (cm2). Thin tubes (d/t > 29) use S355 for section class.
  const RAW = [
    ['60.3', '3.2', 5.74], ['76.1', '3.2', 7.33], ['76.1', '4', 9.06], ['88.9', '4', 10.67],
    ['88.9', '5', 13.18], ['114.3', '4', 13.86], ['114.3', '5', 17.17], ['139.7', '5', 21.16],
    ['168.3', '5', 25.65], ['139.7', '6.3', 26.4], ['168.3', '6.3', 32.06], ['193.7', '6.3', 37.09],
    ['193.7', '8', 46.67], ['219.1', '8', 53.06], ['244.5', '8', 59.44], ['273', '10', 82.62],
    ['323.9', '10', 98.61], ['355.6', '12.5', 134.74], ['406.4', '12.5', 154.68], ['457', '16', 221.67]
  ];
  const LAD = RAW.map(function (s) {
    const ratio = parseFloat(s[0]) / parseFloat(s[1]);
    const mat = ratio <= 29 ? 'S690' : 'S355';
    return { spec: mat + ' CHS' + s[0] + 'x' + s[1], A: s[2] };
  });
  const MAXI = LAD.length - 1;

  function build(topo) {
    const S = topo === 'A' ? 15 : 8;
    const tL = [], tR = [], bL = [], bR = [], nodes = [], mem = [];
    function xOf(k) {
      if (topo === 'B') return XS[k];
      if (k % 2 === 0) return XS[k / 2];
      return (XS[(k - 1) / 2] + XS[(k + 1) / 2]) / 2;
    }
    for (let k = 0; k < S; k++) {
      const x = xOf(k);
      if (topo === 'B' || k % 2 === 0) {
        const j = topo === 'B' ? k : k / 2;
        tL.push('L' + j);
        tR.push('R' + j);
      } else {
        tL.push('LM' + k);
        tR.push('RM' + k);
        nodes.push({ id: 'LM' + k, x: x, y: 0, z: ZL, joint: 'pin' });
        nodes.push({ id: 'RM' + k, x: x, y: 0, z: ZR, joint: 'pin' });
      }
      bL.push('BL' + k);
      bR.push('BR' + k);
      nodes.push({ id: 'BL' + k, x: x, y: HB, z: ZL, joint: 'pin' });
      nodes.push({ id: 'BR' + k, x: x, y: HB, z: ZR, joint: 'pin' });
    }
    function add(a, b, role) { mem.push({ a: a, b: b, role: role }); }
    for (let k = 0; k < S - 1; k++) {
      add(tL[k], tL[k + 1], 'tc');
      add(tR[k], tR[k + 1], 'tc');
      add(bL[k], bL[k + 1], 'bc');
      add(bR[k], bR[k + 1], 'bc');
      if (k % 2 === 0) {
        add(bL[k], tL[k + 1], 'dg');
        add(bR[k], tR[k + 1], 'dg');
      } else {
        add(tL[k], bL[k + 1], 'dg');
        add(tR[k], bR[k + 1], 'dg');
      }
      add(tL[k], tR[k + 1], 'xt');
      add(tR[k], tL[k + 1], 'xt');
      add(bL[k], bR[k + 1], 'xb');
      add(bR[k], bL[k + 1], 'xb');
    }
    for (let k = 0; k < S; k++) {
      add(tL[k], bL[k], 'vt');
      add(tR[k], bR[k], 'vt');
      add(tL[k], tR[k], 'tr');
      add(bL[k], bR[k], 'tb');
      add(tL[k], bR[k], 'cd');
    }
    return { nodes: nodes, mem: mem };
  }

  function sizeTopology(topo, start, maxIt) {
    const b = build(topo);
    const n = b.mem.length;
    const idx = new Array(n).fill(start);
    const dirPrev = new Array(n).fill(0);
    const flips = new Array(n).fill(0);
    let best = null, last = null;
    for (let it = 0; it < maxIt; it++) {
      const d = {
        note: 'iteratively sized box truss, topology ' + topo,
        nodes: b.nodes,
        joints: {},
        members: b.mem.map(function (m, i) {
          return { a: m.a, b: m.b, spec: LAD[idx[i]].spec };
        })
      };
      let r = null;
      try { r = analyse(d); } catch (e) { r = null; }
      if (!r || r.error) break;
      last = d;
      if (r.ok && typeof r.mass === 'number' && (best === null || r.mass < best.mass)) {
        best = { mass: r.mass, d: d };
      }
      const util = new Array(n).fill(0.7);
      if (r.members && r.members.length === n) {
        for (let i = 0; i < n; i++) {
          const u = r.members[i].util;
          if (typeof u === 'number') util[i] = u;
        }
      }
      const sagR = (typeof r.sag === 'number' && r.sagLimit > 0) ? r.sag / r.sagLimit : 0;
      const swayR = (typeof r.sway === 'number' && r.swayLimit > 0) ? r.sway / r.swayLimit : 0;
      const fOK = (typeof r.fMin === 'number') ? r.fMin >= 2.0 : true;
      const aOK = (typeof r.alphaCr === 'number') ? r.alphaCr >= 4.5 : true;
      const chordBad = sagR > 0.95 || swayR > 0.95 || !fOK || !aOK;
      const chordTight = sagR > 0.85 || swayR > 0.85;
      let changed = false;
      for (let i = 0; i < n; i++) {
        if (flips[i] >= 3) continue;
        const role = b.mem[i].role;
        const isChord = role === 'tc' || role === 'bc';
        let dir = 0;
        if (util[i] > 0.95 || (isChord && chordBad)) dir = 1;
        else if (util[i] < 0.5 && !(isChord && chordTight)) dir = -1;
        if (dir === 1 && idx[i] < MAXI) { idx[i]++; changed = true; }
        else if (dir === -1 && idx[i] > 0) { idx[i]--; changed = true; }
        else dir = 0;
        if (dir !== 0) {
          if (dirPrev[i] !== 0 && dir !== dirPrev[i]) flips[i]++;
          dirPrev[i] = dir;
        }
      }
      if (!changed) break;
    }
    return { best: best, last: last };
  }

  const rB = sizeTopology('B', 9, 40);
  const rA = sizeTopology('A', 9, 40);
  let pick = null;
  if (rB.best && (!rA.best || rB.best.mass <= rA.best.mass)) pick = rB.best.d;
  else if (rA.best) pick = rA.best.d;
  else pick = rB.last || rA.last;
  if (!pick) return { note: 'no design produced', nodes: [], joints: {}, members: [] };
  return {
    note: 'Pinned 3D box truss below the deck (Warren sides, top/bottom X-bracing, rungs and cross-diagonals), sized member by member with analyse().',
    nodes: pick.nodes,
    joints: pick.joints,
    members: pick.members
  };
}

function design(site, analyse) {
  // Pratt-type box girder below the deck. Two side trusses (top chord = deck edge,
  // bottom chord at y = -4.7), verticals, Pratt diagonals in tension under gravity,
  // top and bottom lateral bracing (rungs plus X in every panel). Bottom chords,
  // bottom bracing and diagonals can be aluminium 7075 (lower mass per unit tension).
  const XS = [0, 4.914, 9.829, 14.743, 19.657, 24.571, 29.486, 34.4];
  const HB = -4.7, ZL = -2.35, ZR = 2.35;

  // CHS ladder by ascending area (cm2)
  const SEC = [
    ['33.7', '2.6', 2.54], ['42.4', '3.2', 3.94], ['48.3', '3.2', 4.53], ['60.3', '3.2', 5.74],
    ['60.3', '4', 7.07], ['76.1', '3.2', 7.33], ['76.1', '4', 9.06], ['88.9', '4', 10.67],
    ['88.9', '5', 13.18], ['114.3', '4', 13.86], ['114.3', '5', 17.17], ['139.7', '5', 21.16],
    ['168.3', '5', 25.65], ['139.7', '6.3', 26.4], ['168.3', '6.3', 32.06], ['193.7', '6.3', 37.09],
    ['193.7', '8', 46.67], ['219.1', '8', 53.06], ['244.5', '8', 59.44], ['273', '10', 82.62],
    ['323.9', '10', 98.61], ['355.6', '12.5', 134.74], ['406.4', '12.5', 154.68], ['457', '16', 221.67]
  ];
  const MAXI = SEC.length - 1;

  // Starting ladder index per role
  const START = { tc: 14, bc: 14, vt: 10, dg: 11, rt: 7, rb: 7, xt: 6, xb: 6 };

  function specOf(k, al) {
    const d = parseFloat(SEC[k][0]), t = parseFloat(SEC[k][1]);
    const tag = SEC[k][0] + 'x' + SEC[k][1];
    if (al) return 'AL7075 CHS' + tag;
    return (d / t <= 29 ? 'S690' : 'S355') + ' CHS' + tag;
  }

  // Topology
  const nodes = [];
  for (let j = 0; j < 8; j++) {
    nodes.push({ id: 'BL' + j, x: XS[j], y: HB, z: ZL, joint: 'pin' });
    nodes.push({ id: 'BR' + j, x: XS[j], y: HB, z: ZR, joint: 'pin' });
  }
  const mem = [];
  function add(a, b, role) { mem.push({ a: a, b: b, role: role }); }
  for (let j = 0; j < 7; j++) {
    add('L' + j, 'L' + (j + 1), 'tc');
    add('R' + j, 'R' + (j + 1), 'tc');
    add('BL' + j, 'BL' + (j + 1), 'bc');
    add('BR' + j, 'BR' + (j + 1), 'bc');
    add('L' + j, 'R' + (j + 1), 'xt');
    add('R' + j, 'L' + (j + 1), 'xt');
    add('BL' + j, 'BR' + (j + 1), 'xb');
    add('BR' + j, 'BL' + (j + 1), 'xb');
  }
  for (let j = 0; j < 8; j++) {
    add('L' + j, 'BL' + j, 'vt');
    add('R' + j, 'BR' + j, 'vt');
    add('L' + j, 'R' + j, 'rt');
    add('BL' + j, 'BR' + j, 'rb');
  }
  const SIDES = [['L', 'BL'], ['R', 'BR']];
  for (const sd of SIDES) {
    const T = sd[0], B = sd[1];
    for (let p = 0; p < 3; p++) add(T + p, B + (p + 1), 'dg');       // Pratt, left half
    for (let p = 4; p < 7; p++) add(T + (p + 1), B + p, 'dg');       // Pratt, right half
    add(T + 3, B + 4, 'dg');                                          // centre panel X
    add(T + 4, B + 3, 'dg');
  }

  function run(alRoles, maxIt) {
    const n = mem.length;
    const idx = mem.map(function (m) { return START[m.role]; });
    const dirPrev = new Array(n).fill(0);
    const flips = new Array(n).fill(0);
    let best = null, last = null;
    for (let it = 0; it < maxIt; it++) {
      const d = {
        note: 'Pratt box girder with lateral bracing, sized member by member with analyse().',
        nodes: nodes,
        joints: {},
        members: mem.map(function (m, i) {
          return { a: m.a, b: m.b, spec: specOf(idx[i], !!alRoles[m.role]) };
        })
      };
      let r = null;
      try { r = analyse(d); } catch (e) { r = null; }
      if (!r || r.error) break;
      last = { d: d, r: r };
      if (r.ok && typeof r.mass === 'number' && (best === null || r.mass < best.mass)) {
        best = { mass: r.mass, d: d };
      }
      const util = new Array(n).fill(0.7);
      if (r.members && r.members.length === n) {
        for (let i = 0; i < n; i++) {
          if (typeof r.members[i].util === 'number') util[i] = r.members[i].util;
        }
      }
      const sagR = (typeof r.sag === 'number' && r.sagLimit > 0) ? r.sag / r.sagLimit : 0;
      const swayR = (typeof r.sway === 'number' && r.swayLimit > 0) ? r.sway / r.swayLimit : 0;
      const fLow = (typeof r.fMin === 'number') ? r.fMin < 2.1 : false;
      const aLow = (typeof r.alphaCr === 'number') ? r.alphaCr < 4.6 : false;
      const stiff = sagR > 0.9 || fLow;

      let changed = false;
      for (let i = 0; i < n; i++) {
        if (flips[i] >= 3) continue;
        const role = mem[i].role;
        let dir = 0;
        if (util[i] > 0.92) dir = 1;
        else if (util[i] < 0.45) dir = -1;
        if (stiff && (role === 'tc' || role === 'bc' || role === 'dg')) dir = 1;
        if (swayR > 0.9 && (role === 'rt' || role === 'rb' || role === 'xt' || role === 'xb')) dir = 1;
        if (aLow && (role === 'tc' || role === 'xt' || role === 'xb' || role === 'rt')) dir = 1;
        if (dir === 1 && idx[i] < MAXI) { idx[i]++; changed = true; }
        else if (dir === -1 && idx[i] > 0) { idx[i]--; changed = true; }
        else dir = 0;
        if (dir !== 0) {
          if (dirPrev[i] !== 0 && dir !== dirPrev[i]) flips[i]++;
          dirPrev[i] = dir;
        }
      }
      if (!changed) break;
    }
    return { best: best, last: last };
  }

  // Material variants: which roles use aluminium 7075 (lower mass per unit strength)
  const variants = [
    {},
    { bc: true, rb: true, xb: true },
    { bc: true, rb: true, xb: true, dg: true },
    { bc: true, rb: true, xb: true, dg: true, rt: true, xt: true }
  ];

  let overall = null, lastAll = null;
  for (const v of variants) {
    const res = run(v, 45);
    if (res.best && (overall === null || res.best.mass < overall.mass)) overall = res.best;
    if (res.last) lastAll = res.last.d;
  }
  const pick = overall ? overall.d : lastAll;
  if (!pick) return { note: 'no design produced', nodes: [], joints: {}, members: [] };
  return {
    note: 'Pratt box girder below deck (pinned), top/bottom lateral X-bracing, Al7075 bottom chords and bracing where tension-dominated; sized member by member with analyse().',
    nodes: pick.nodes,
    joints: pick.joints,
    members: pick.members
  };
}

function design(site, analyse) {
  // Below-deck box truss, two topologies:
  //   A = Warren sides with mid-panel top nodes (short compression chords)
  //   B = Warren sides on deck stations only
  // Roles: tc/bc chords, dg diagonals, vt verticals, tr/tb transverse rungs,
  // xt/xb lateral X-bracing, cd transverse cross-diagonals.
  // Each role is sized by bisection on a CHS ladder, may be dropped entirely,
  // and may be steel (S690, or S355 for d/t > 29) or AL7075.
  // Only analysed designs that pass with margin are kept.
  const XS = [0, 4.914, 9.829, 14.743, 19.657, 24.571, 29.486, 34.4];
  const ZL = -2.35, ZR = 2.35, HB = -4.7;
  const LIM = 0.85, SAGR = 0.9, FMIN = 2.0, ACRMIN = 4.5;
  const BUDGET = 385;

  // CHS ladder by ascending area: [diameter, wall, area cm2]
  const SEC = [
    ['33.7', '2.6', 2.54], ['42.4', '3.2', 3.94], ['48.3', '3.2', 4.53], ['60.3', '3.2', 5.74],
    ['60.3', '4', 7.07], ['76.1', '3.2', 7.33], ['76.1', '4', 9.06], ['88.9', '4', 10.67],
    ['88.9', '5', 13.18], ['114.3', '4', 13.86], ['114.3', '5', 17.17], ['139.7', '5', 21.16],
    ['168.3', '5', 25.65], ['139.7', '6.3', 26.4], ['168.3', '6.3', 32.06], ['193.7', '6.3', 37.09],
    ['193.7', '8', 46.67], ['219.1', '8', 53.06], ['244.5', '8', 59.44], ['273', '10', 82.62],
    ['323.9', '10', 98.61], ['355.6', '12.5', 134.74], ['406.4', '12.5', 154.68], ['457', '16', 221.67]
  ];
  const NS = SEC.length;
  const ROLES = ['tc', 'bc', 'dg', 'vt', 'tb', 'tr', 'xb', 'xt', 'cd'];

  function specOf(i, mat) {
    const d = SEC[i][0], t = SEC[i][1];
    let m;
    if (mat === 'AL') m = 'AL7075';
    else m = (parseFloat(d) / parseFloat(t) <= 29) ? 'S690' : 'S355';
    return m + ' CHS' + d + 'x' + t;
  }

  function build(topo) {
    const S = topo === 'A' ? 15 : 8;
    const tL = [], tR = [], bL = [], bR = [], nodes = [], mem = [];
    function xOf(k) {
      if (topo === 'B') return XS[k];
      if (k % 2 === 0) return XS[k / 2];
      return (XS[(k - 1) / 2] + XS[(k + 1) / 2]) / 2;
    }
    for (let k = 0; k < S; k++) {
      const x = xOf(k);
      if (topo === 'B' || k % 2 === 0) {
        const j = topo === 'B' ? k : k / 2;
        tL.push('L' + j);
        tR.push('R' + j);
      } else {
        tL.push('LM' + k);
        tR.push('RM' + k);
        nodes.push({ id: 'LM' + k, x: x, y: 0, z: ZL, joint: 'pin' });
        nodes.push({ id: 'RM' + k, x: x, y: 0, z: ZR, joint: 'pin' });
      }
      bL.push('BL' + k);
      bR.push('BR' + k);
      nodes.push({ id: 'BL' + k, x: x, y: HB, z: ZL, joint: 'pin' });
      nodes.push({ id: 'BR' + k, x: x, y: HB, z: ZR, joint: 'pin' });
    }
    function add(a, b, role) { mem.push({ a: a, b: b, role: role }); }
    for (let k = 0; k < S - 1; k++) {
      add(tL[k], tL[k + 1], 'tc');
      add(tR[k], tR[k + 1], 'tc');
      add(bL[k], bL[k + 1], 'bc');
      add(bR[k], bR[k + 1], 'bc');
      if (k % 2 === 0) {
        add(bL[k], tL[k + 1], 'dg');
        add(bR[k], tR[k + 1], 'dg');
      } else {
        add(tL[k], bL[k + 1], 'dg');
        add(tR[k], bR[k + 1], 'dg');
      }
      add(tL[k], tR[k + 1], 'xt');
      add(tR[k], tL[k + 1], 'xt');
      add(bL[k], bR[k + 1], 'xb');
      add(bR[k], bL[k + 1], 'xb');
    }
    for (let k = 0; k < S; k++) {
      add(tL[k], bL[k], 'vt');
      add(tR[k], bR[k], 'vt');
      add(tL[k], tR[k], 'tr');
      add(bL[k], bR[k], 'tb');
      add(tL[k], bR[k], 'cd');
    }
    return { name: topo, nodes: nodes, mem: mem };
  }

  function makeDesign(T, cfg) {
    const members = [];
    for (const m of T.mem) {
      const c = cfg[m.role];
      if (!c || c.drop) continue;
      members.push({ a: m.a, b: m.b, spec: specOf(c.idx, c.mat) });
    }
    return {
      note: 'Box truss below deck, topology ' + T.name + ', roles bisection-sized with analyse().',
      nodes: T.nodes,
      joints: {},
      members: members
    };
  }

  function isOK(r) {
    if (!r || r.error || !r.ok) return false;
    if (typeof r.maxUtil === 'number' && r.maxUtil > LIM) return false;
    if (typeof r.sag === 'number' && r.sagLimit > 0 && r.sag > SAGR * r.sagLimit) return false;
    if (typeof r.sway === 'number' && r.swayLimit > 0 && r.sway > SAGR * r.swayLimit) return false;
    if (typeof r.fMin === 'number' && r.fMin < FMIN) return false;
    if (typeof r.alphaCr === 'number' && r.alphaCr < ACRMIN) return false;
    return true;
  }

  const cache = {};
  let calls = 0;
  let bestOut = null;

  function evalCfg(T, cfg) {
    const key = T.name + '|' + ROLES.map(function (r) {
      const c = cfg[r];
      return c.drop ? 'D' : (c.idx + c.mat);
    }).join(',');
    if (cache[key]) return cache[key];
    if (calls >= BUDGET) return null;
    calls++;
    const d = makeDesign(T, cfg);
    let r = null;
    try { r = analyse(d); } catch (e) { r = null; }
    const ok = isOK(r);
    const mass = (r && typeof r.mass === 'number') ? r.mass : Infinity;
    const out = { ok: ok, mass: mass, cfg: JSON.parse(JSON.stringify(cfg)), d: d };
    cache[key] = out;
    if (ok && mass < (bestOut ? bestOut.mass : Infinity)) bestOut = out;
    return out;
  }

  function at(T, base, role, idx, mat) {
    const c = JSON.parse(JSON.stringify(base));
    c[role] = { drop: false, idx: idx, mat: mat };
    return evalCfg(T, c);
  }

  // Minimal feasible ladder index for one role/material, others fixed.
  function search(T, base, role, mat, hint) {
    let hi = hint;
    let best = at(T, base, role, hi, mat);
    if (!best || !best.ok) {
      hi = NS - 1;
      best = at(T, base, role, hi, mat);
      if (!best || !best.ok) return null;
    }
    let lo = 0;
    while (lo < hi) {
      const mid = Math.floor((lo + hi) / 2);
      const o = at(T, base, role, mid, mat);
      if (o && o.ok) { hi = mid; best = o; } else { lo = mid + 1; }
    }
    return best;
  }

  function sweep(T, cur, mode) {
    for (const role of ROLES) {
      const c0 = cur.cfg[role];
      if (mode === 1 && !c0.drop) {
        const cdrop = JSON.parse(JSON.stringify(cur.cfg));
        cdrop[role] = { drop: true };
        const o = evalCfg(T, cdrop);
        if (o && o.ok && o.mass < cur.mass) { cur = o; continue; }
      }
      const mats = mode === 1 ? ['STEEL', 'AL'] : [c0.drop ? 'STEEL' : c0.mat];
      const hint = c0.drop ? NS - 1 : c0.idx;
      let bestHere = null;
      for (const mat of mats) {
        const o = search(T, cur.cfg, role, mat, hint);
        if (o && (!bestHere || o.mass < bestHere.mass)) bestHere = o;
      }
      if (bestHere && bestHere.mass < cur.mass) cur = bestHere;
    }
    return cur;
  }

  function runTopo(T) {
    const base = {};
    ROLES.forEach(function (r) { base[r] = { drop: false, idx: NS - 1, mat: 'STEEL' }; });
    let cur = evalCfg(T, base);
    if (!cur || !cur.ok) return;
    cur = sweep(T, cur, 1);
    cur = sweep(T, cur, 2);
  }

  runTopo(build('A'));
  runTopo(build('B'));

  if (!bestOut) return { note: 'no feasible design found', nodes: [], joints: {}, members: [] };
  return bestOut.d;
}

function design(site, analyse) {
  // Warren box truss below the deck, two variants:
  //   D = 8 stations on the deck nodes (4.914 m panels)
  //   F = 15 stations, mid-panel top nodes added (2.457 m panels, shorter chord buckling lengths)
  // Every station has a vertical, top and bottom rungs and one cross-diagonal (L_k to BR_k),
  // which triangulates each cross-frame and removes the racking mechanism of attempt 2.
  // Every panel has top and bottom X-bracing. Roles are sized by bisection on a CHS ladder,
  // each with steel (S690, or S355 where d/t > 29) or AL7075.
  const XS = [0, 4.914, 9.829, 14.743, 19.657, 24.571, 29.486, 34.4];
  const HB = -4.7, ZL = -2.35, ZR = 2.35;

  const SEC = [
    ['33.7', '2.6', 2.54], ['42.4', '3.2', 3.94], ['48.3', '3.2', 4.53], ['60.3', '3.2', 5.74],
    ['60.3', '4', 7.07], ['76.1', '3.2', 7.33], ['76.1', '4', 9.06], ['88.9', '4', 10.67],
    ['88.9', '5', 13.18], ['114.3', '4', 13.86], ['114.3', '5', 17.17], ['139.7', '5', 21.16],
    ['168.3', '5', 25.65], ['139.7', '6.3', 26.4], ['168.3', '6.3', 32.06], ['193.7', '6.3', 37.09],
    ['193.7', '8', 46.67], ['219.1', '8', 53.06], ['244.5', '8', 59.44], ['273', '10', 82.62],
    ['323.9', '10', 98.61], ['355.6', '12.5', 134.74], ['406.4', '12.5', 154.68], ['457', '16', 221.67]
  ];
  const NS = SEC.length;
  const ROLES = ['tc', 'bc', 'dg', 'vt', 'tr', 'tb', 'xt', 'xb', 'cd'];
  const MATS = ['S', 'AL'];
  const BUDGET = 388;
  // Margins for unseen units: strength/thickness down to ~92%, E down 3%, wall 8% thinner
  const UMAX = 0.85, SAGR = 0.85, SWAYR = 0.85, FMIN = 2.1, ACRMIN = 4.8;

  function specOf(i, mat) {
    const d = SEC[i][0], t = SEC[i][1];
    let m;
    if (mat === 'AL') m = 'AL7075';
    else m = (parseFloat(d) / parseFloat(t) <= 29) ? 'S690' : 'S355';
    return m + ' CHS' + d + 'x' + t;
  }

  function xAt(fine, k) {
    if (!fine) return XS[k];
    if (k % 2 === 0) return XS[k / 2];
    return (XS[(k - 1) / 2] + XS[(k + 1) / 2]) / 2;
  }

  function build(fine) {
    const S = fine ? 15 : 8;
    const tL = [], tR = [], bL = [], bR = [], nodes = [], mem = [];
    for (let k = 0; k < S; k++) {
      const x = xAt(fine, k);
      if (!fine || k % 2 === 0) {
        const j = fine ? k / 2 : k;
        tL.push('L' + j);
        tR.push('R' + j);
      } else {
        tL.push('LM' + k);
        tR.push('RM' + k);
        nodes.push({ id: 'LM' + k, x: x, y: 0, z: ZL, joint: 'pin' });
        nodes.push({ id: 'RM' + k, x: x, y: 0, z: ZR, joint: 'pin' });
      }
      bL.push('BL' + k);
      bR.push('BR' + k);
      nodes.push({ id: 'BL' + k, x: x, y: HB, z: ZL, joint: 'pin' });
      nodes.push({ id: 'BR' + k, x: x, y: HB, z: ZR, joint: 'pin' });
    }
    function add(a, b, role) { mem.push({ a: a, b: b, role: role }); }
    for (let k = 0; k < S - 1; k++) {
      add(tL[k], tL[k + 1], 'tc');
      add(tR[k], tR[k + 1], 'tc');
      add(bL[k], bL[k + 1], 'bc');
      add(bR[k], bR[k + 1], 'bc');
      if (k % 2 === 0) {
        add(bL[k], tL[k + 1], 'dg');
        add(bR[k], tR[k + 1], 'dg');
      } else {
        add(tL[k], bL[k + 1], 'dg');
        add(tR[k], bR[k + 1], 'dg');
      }
      add(tL[k], tR[k + 1], 'xt');
      add(tR[k], tL[k + 1], 'xt');
      add(bL[k], bR[k + 1], 'xb');
      add(bR[k], bL[k + 1], 'xb');
    }
    for (let k = 0; k < S; k++) {
      add(tL[k], bL[k], 'vt');
      add(tR[k], bR[k], 'vt');
      add(tL[k], tR[k], 'tr');
      add(bL[k], bR[k], 'tb');
      add(tL[k], bR[k], 'cd');
    }
    return { name: fine ? 'F' : 'D', nodes: nodes, mem: mem };
  }

  function makeDesign(T, cfg) {
    const members = [];
    for (const m of T.mem) {
      const c = cfg[m.role];
      members.push({ a: m.a, b: m.b, spec: specOf(c.idx, c.mat) });
    }
    return {
      note: 'Warren box truss below deck (' + T.name + ' topology) with cross-diagonals in every station, roles bisection-sized with analyse().',
      nodes: T.nodes,
      joints: {},
      members: members
    };
  }

  function isOK(r) {
    if (!r || r.error || !r.ok) return false;
    if (typeof r.maxUtil === 'number' && r.maxUtil > UMAX) return false;
    if (typeof r.sag === 'number' && r.sagLimit > 0 && r.sag > SAGR * r.sagLimit) return false;
    if (typeof r.sway === 'number' && r.swayLimit > 0 && r.sway > SWAYR * r.swayLimit) return false;
    if (typeof r.fMin === 'number' && r.fMin < FMIN) return false;
    if (typeof r.alphaCr === 'number' && r.alphaCr < ACRMIN) return false;
    return true;
  }

  let calls = 0;
  const cache = {};
  let best = null;
  let fallback = null;

  function evalCfg(T, cfg) {
    const key = T.name + '|' + ROLES.map(function (r) { return cfg[r].idx + cfg[r].mat; }).join(',');
    if (Object.prototype.hasOwnProperty.call(cache, key)) return cache[key];
    if (calls >= BUDGET) return null;
    calls++;
    const d = makeDesign(T, cfg);
    let r = null;
    try { r = analyse(d); } catch (e) { r = null; }
    const ok = isOK(r);
    const mass = (r && typeof r.mass === 'number') ? r.mass : Infinity;
    const out = { ok: ok, mass: mass, cfg: JSON.parse(JSON.stringify(cfg)), d: d };
    cache[key] = out;
    if (ok && (best === null || mass < best.mass)) best = out;
    if (fallback === null) fallback = out;
    return out;
  }

  function withRole(cfg, role, idx, mat) {
    const c = JSON.parse(JSON.stringify(cfg));
    c[role] = { idx: idx, mat: mat };
    return c;
  }

  // Smallest feasible ladder index for one role/material. If hint is given it is assumed feasible.
  function minimise(T, cfg, role, mat, hint) {
    let hi = (hint === undefined) ? NS - 1 : hint;
    if (hint === undefined) {
      const t = evalCfg(T, withRole(cfg, role, hi, mat));
      if (!t || !t.ok) return null;
    }
    let lo = 0;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      const o = evalCfg(T, withRole(cfg, role, mid, mat));
      if (o === null) return null;
      if (o.ok) hi = mid; else lo = mid + 1;
    }
    const fin = evalCfg(T, withRole(cfg, role, hi, mat));
    return (fin && fin.ok) ? fin : null;
  }

  function sweep(T, cur) {
    for (const role of ROLES) {
      let here = cur;
      for (const mat of MATS) {
        const same = cur.cfg[role].mat === mat;
        const hint = same ? cur.cfg[role].idx : undefined;
        const o = minimise(T, cur.cfg, role, mat, hint);
        if (o && o.ok && o.mass < here.mass) here = o;
      }
      cur = here;
    }
    return cur;
  }

  const states = [];
  for (const fine of [false, true]) {
    const T = build(fine);
    const base = {};
    for (const r of ROLES) base[r] = { idx: NS - 1, mat: 'S' };
    const start = evalCfg(T, base);
    if (start && start.ok) {
      states.push({ T: T, cur: sweep(T, start) });
    }
  }
  states.sort(function (a, b) { return a.cur.mass - b.cur.mass; });
  for (const s of states) {
    s.cur = sweep(s.T, s.cur);
  }

  if (best) {
    return {
      note: best.d.note,
      nodes: best.d.nodes,
      joints: {},
      members: best.d.members
    };
  }
  if (fallback) {
    return {
      note: 'No passing design found; returning the all-large start design for diagnosis.',
      nodes: fallback.d.nodes,
      joints: {},
      members: fallback.d.members
    };
  }
  return { note: 'no design produced', nodes: [], joints: {}, members: [] };
}

function design(site, analyse) {
  const t0 = Date.now();
  const XS = [0, 4.914, 9.829, 14.743, 19.657, 24.571, 29.486, 34.4];
  const ZL = -2.35, ZR = 2.35, HB = -4.7;
  const UT = 0.70, UOK = 0.75, SAGOK = 0.85, SWOK = 0.85, FATOK = 0.85;
  const ACROK = 4.8, FRQOK = 2.1, ITER = 12, TLIM = 60000, CALLMAX = 300;
  const SIGF = { S: 113.4e6, W: 138.6e6 }; // fatigue Δσ × 2^(1/3), pinned

  const CHS_RAW = [
    ['33.7', '2.6', 2.54], ['42.4', '3.2', 3.94], ['48.3', '3.2', 4.53], ['60.3', '3.2', 5.74],
    ['60.3', '4', 7.07], ['76.1', '3.2', 7.33], ['76.1', '4', 9.06], ['88.9', '4', 10.67],
    ['88.9', '5', 13.18], ['114.3', '4', 13.86], ['114.3', '5', 17.17], ['139.7', '5', 21.16],
    ['139.7', '6.3', 26.4], ['168.3', '5', 25.65], ['168.3', '6.3', 32.06], ['193.7', '6.3', 37.09],
    ['193.7', '8', 46.67], ['219.1', '8', 53.06], ['244.5', '8', 59.44], ['273', '10', 82.62],
    ['323.9', '10', 98.61], ['355.6', '12.5', 134.74], ['406.4', '12.5', 154.68], ['457', '16', 221.67]
  ];
  const WIRE_RAW = [['8', 0.3], ['10', 0.47], ['12', 0.68], ['16', 1.21], ['20', 1.88],
                    ['24', 2.71], ['32', 4.83], ['40', 7.54]];

  const CHS = CHS_RAW.map(function (c) {
    const mat = (parseFloat(c[0]) / parseFloat(c[1]) <= 30) ? 'S690' : 'S355';
    return { spec: mat + ' CHS' + c[0] + 'x' + c[1], A: c[2] };
  }).sort(function (p, q) { return p.A - q.A; });
  const WIRE = WIRE_RAW.map(function (w) { return { spec: 'WIRE WIRE' + w[0], A: w[1] }; });

  // Warren box truss below deck. fine = true adds mid-panel top nodes (shorter chord panels).
  function build(fine) {
    const S = fine ? 15 : 8;
    const tL = [], tR = [], bL = [], bR = [], nodes = [], mem = [];
    function xAt(k) {
      if (!fine || k % 2 === 0) return XS[fine ? k / 2 : k];
      return (XS[(k - 1) / 2] + XS[(k + 1) / 2]) / 2;
    }
    for (let k = 0; k < S; k++) {
      const x = xAt(k);
      if (!fine || k % 2 === 0) {
        const j = fine ? k / 2 : k;
        tL.push('L' + j); tR.push('R' + j);
      } else {
        tL.push('LM' + k); tR.push('RM' + k);
        nodes.push({ id: 'LM' + k, x: x, y: 0, z: ZL, joint: 'pin' });
        nodes.push({ id: 'RM' + k, x: x, y: 0, z: ZR, joint: 'pin' });
      }
      bL.push('BL' + k); bR.push('BR' + k);
      nodes.push({ id: 'BL' + k, x: x, y: HB, z: ZL, joint: 'pin' });
      nodes.push({ id: 'BR' + k, x: x, y: HB, z: ZR, joint: 'pin' });
    }
    function add(a, b, role) { mem.push({ a: a, b: b, role: role }); }
    for (let k = 0; k < S - 1; k++) {
      add(tL[k], tL[k + 1], 'tc');
      add(tR[k], tR[k + 1], 'tc');
      add(bL[k], bL[k + 1], 'bc');
      add(bR[k], bR[k + 1], 'bc');
      if (k % 2 === 0) {
        add(bL[k], tL[k + 1], 'dg');
        add(bR[k], tR[k + 1], 'dg');
      } else {
        add(tL[k], bL[k + 1], 'dg');
        add(tR[k], bR[k + 1], 'dg');
      }
      add(tL[k], tR[k + 1], 'xt');
      add(tR[k], tL[k + 1], 'xt');
      add(bL[k], bR[k + 1], 'xb');
      add(bR[k], bL[k + 1], 'xb');
    }
    for (let k = 0; k < S; k++) {
      add(tL[k], bL[k], 'vt');
      add(tR[k], bR[k], 'vt');
      add(tL[k], tR[k], 'tr');
      add(bL[k], bR[k], 'tb');
      add(tL[k], bR[k], 'cd');
    }
    return { nodes: nodes, mem: mem };
  }
  const TOP = { D: build(false), F: build(true) };

  function optsFor(V, role) {
    return ((role === 'xt' || role === 'xb') && V.wireX) ? WIRE : CHS;
  }

  function mkDesign(T, mem, V, st, note) {
    const members = [];
    for (let i = 0; i < mem.length; i++) {
      const o = optsFor(V, mem[i].role)[st[i]];
      members.push({ a: mem[i].a, b: mem[i].b, spec: o.spec });
    }
    return { note: note, nodes: T.nodes, joints: {}, members: members };
  }

  function maxUtilOf(r) {
    let mx = (typeof r.maxUtil === 'number') ? r.maxUtil : 0;
    (r.members || []).forEach(function (e) {
      if (typeof e.util === 'number' && e.util > mx) mx = e.util;
    });
    return mx;
  }

  function isOK(r) {
    if (!r || r.error || r.ok === false) return false;
    if (typeof r.mass !== 'number') return false;
    if (maxUtilOf(r) > UOK) return false;
    if (typeof r.sag === 'number' && r.sagLimit > 0 && r.sag > SAGOK * r.sagLimit) return false;
    if (typeof r.sway === 'number' && r.swayLimit > 0 && r.sway > SWOK * r.swayLimit) return false;
    if (typeof r.frequency === 'number' && r.frequency < FRQOK) return false;
    if (typeof r.alphaCr === 'number' && r.alphaCr < ACROK) return false;
    if (typeof r.fatigueWorst === 'number' && r.fatigueWorst > FATOK) return false;
    return true;
  }

  function needsStiff(r) {
    if (typeof r.sag === 'number' && r.sagLimit > 0 && r.sag > SAGOK * r.sagLimit) return true;
    if (typeof r.sway === 'number' && r.swayLimit > 0 && r.sway > SWOK * r.swayLimit) return true;
    if (typeof r.alphaCr === 'number' && r.alphaCr < ACROK) return true;
    if (typeof r.frequency === 'number' && r.frequency < FRQOK) return true;
    return false;
  }

  function utilIndex(r) {
    const map = {};
    (r.members || []).forEach(function (e) { map[e.id] = e; });
    return map;
  }
  function findEntry(map, a, b) {
    return map[a + '-' + b] || map[b + '-' + a] || null;
  }

  let calls = 0;
  function callA(d) {
    if (Date.now() - t0 > TLIM) return null;
    if (calls >= CALLMAX) return null;
    calls++;
    try { return analyse(d); } catch (e) { return null; }
  }

  function runVariant(V) {
    const T = TOP[V.fine ? 'F' : 'D'];
    const mem = T.mem.filter(function (m) { return !(V.dropVt && m.role === 'vt'); });
    const st = mem.map(function (m) {
      const o = optsFor(V, m.role);
      if (o === WIRE) return WIRE.length - 1;
      const j = CHS.findIndex(function (c) { return c.A >= 46.6; });
      return j < 0 ? CHS.length - 1 : j;
    });
    let fatFrac = 0.3, stiff = 1.0, best = null;
    for (let it = 0; it < ITER; it++) {
      const d = mkDesign(T, mem, V, st, 'variant ' + V.name);
      const r = callA(d);
      if (!r || r.error) break;
      if (isOK(r) && (best === null || r.mass < best.mass)) {
        best = { mass: r.mass, d: d, name: V.name };
      }
      if (typeof r.fatigueWorst === 'number') {
        if (r.fatigueWorst > 0.8) fatFrac *= 1.2;
        else if (r.fatigueWorst < 0.5) fatFrac = Math.max(0.05, fatFrac * 0.9);
      }
      if (needsStiff(r)) stiff *= 1.1;

      const map = utilIndex(r);
      let changed = false;
      for (let i = 0; i < mem.length; i++) {
        const opts = optsFor(V, mem[i].role);
        const cur = opts[st[i]];
        const e = findEntry(map, mem[i].a, mem[i].b);
        let f = 1, tt = 0, cc = 0;
        if (e) {
          f = (typeof e.util === 'number' ? e.util : 0) / UT;
          tt = Math.abs(e.tension || 0);
          cc = Math.abs(e.compression || 0);
        }
        if (f < 0.2) f = 0.2;
        if (f > 2.5) f = 2.5;
        const sig = (opts === WIRE) ? SIGF.W : SIGF.S;
        const floorA = fatFrac * (tt + cc) * 1000 / sig * 1e4; // cm²
        const need = Math.max(cur.A * f * stiff, floorA);
        let j = opts.findIndex(function (o) { return o.A >= need; });
        if (j < 0) j = opts.length - 1;
        if (j !== st[i]) { st[i] = j; changed = true; }
      }
      if (!changed) break;
    }
