    { name: 'D-tube', fine: false, wireX: false, dropVt: false },
    { name: 'F-wire', fine: true, wireX: true, dropVt: false },
    { name: 'D-wire', fine: false, wireX: true, dropVt: false },
    { name: 'F-tube', fine: true, wireX: false, dropVt: false },
    { name: 'F-wire-noVt', fine: true, wireX: true, dropVt: true },
    { name: 'D-wire-noVt', fine: false, wireX: true, dropVt: true },
    { name: 'D-tube-noVt', fine: false, wireX: false, dropVt: true }
  ];

  let best = null;
  for (let v = 0; v < VARS.length; v++) {
    if (Date.now() - t0 > TLIM) break;
    const b = runVariant(VARS[v]);
    if (b && (best === null || b.mass < best.mass)) best = b;
  }

  if (best) {
    return {
      note: 'Pinned Warren box truss below deck (' + best.name + '), top/bottom X-bracing and rungs; every member sized by fully-stressed iteration on analyse() utilisations with a fatigue floor.',
      nodes: best.d.nodes,
      joints: {},
      members: best.d.members
    };
  }

  // Fallback: uniform large D truss (previously reported as passing).
  const TD = TOP.D;
  const VF = { name: 'fallback', fine: false, wireX: false, dropVt: false };
  const stF = TD.mem.map(function () { return CHS.length - 1; });
  const fb = mkDesign(TD, TD.mem, VF, stF, 'uniform large fallback truss');
  return { note: fb.note, nodes: fb.nodes, joints: {}, members: fb.members };
}

