    if (dt <= 28) g = 'S690'; else if (dt <= 54) g = 'S355';
    if (g === null) return;
    const fy = (g === 'S690') ? 690 : 355;
    OPTS.push({ spec: g + ' CHS' + c[0] + 'x' + c[1], A: c[2], Sa: c[2] * fy / 690 });
  });
