    }
    if (best === null) best = OPTS[OPTS.length - 1];
    return best;
  }

  let calls = 0;
  function callA(d) {
    if (calls >= CALLMAX || Date.now() - t0 > TLIM) return null;
    calls++;
    try { return analyse(d); } catch (e) { return null; }
  }

  // Warren box truss below deck. fine = true adds mid-panel top nodes.
  function build(fine) {
