    for (let i = 0; i < n; i++) { cur.push(pick(17.2)); floor.push(0); }
    let best = null, first = null;
    for (let it = 0; it < ITER; it++) {
      if (Date.now() - t0 > TLIM) break;
      const members = [];
      for (let i = 0; i < n; i++) members.push({ a: mem[i].a, b: mem[i].b, spec: cur[i].spec });
      const d = {
        note: 'Pinned Warren box truss below deck (' + V.name + '), top/bottom X-bracing; members fully-stressed on analyse() utilisations with stiffness floors.',
        nodes: T.nodes, joints: {}, members: members
      };
      if (first === null) first = d;
      const r = callA(d);
      if (!r || r.error || !r.members || r.members.length === 0) break;
      const okNow = passes(r);
      if (okNow && (best === null || r.mass < best.mass)) best = { mass: r.mass, d: d, name: V.name };

      let changed = false;
      const sagBad = isSagBad(r), otherBad = isOtherBad(r);
      if (sagBad || otherBad) {
