    const S = fine ? 15 : 8;
    const tL = [], tR = [], bL = [], bR = [], nodes = [], mem = [];
    for (let k = 0; k < S; k++) {
      const onDeck = (!fine) || (k % 2 === 0);
      const x = onDeck ? XS[fine ? k / 2 : k] : (XS[(k - 1) / 2] + XS[(k + 1) / 2]) / 2;
      if (onDeck) {
        const j = fine ? k / 2 : k;
        tL.push('L' + j); tR.push('R' + j);
      } else {
        tL.push('LM' + k); tR.push('RM' + k);
        nodes.push({ id: 'LM' + k, x: x, y: 0, z: ZL, joint: 'pin' });
        nodes.push({ id: 'RM' + k, x: x, y: 0, z: ZR, joint: 'pin' });
      }
      bL.push('BL' + k); bR.push('BR' + k);
      nodes.push({ id: 'BL' + k, x: x, y: HB, z: ZL, joint: 'pin' });
      nodes.push({ id: 'BR' + k, x: x, y: HB, z: ZR, joint: 'pin' });
    }
    function add(a, b, role) { mem.push({ a: a, b: b, role: role }); }
    const nb = S - 1;
    for (let k = 0; k < nb; k++) {
      add(tL[k], tL[k + 1], 'tc');
      add(tR[k], tR[k + 1], 'tc');
      add(bL[k], bL[k + 1], 'bc');
      add(bR[k], bR[k + 1], 'bc');
      let topFirst;
      if (pratt) topFirst = (k < nb / 2);
      else topFirst = (k % 2 === 1);
      if (topFirst) {
        add(tL[k], bL[k + 1], 'dg');
        add(tR[k], bR[k + 1], 'dg');
      } else {
        add(bL[k], tL[k + 1], 'dg');
        add(bR[k], tR[k + 1], 'dg');
      }
      add(tL[k], tR[k + 1], 'xt');
      add(tR[k], tL[k + 1], 'xt');
      add(bL[k], bR[k + 1], 'xb');
      add(bR[k], bL[k + 1], 'xb');
    }
    for (let k = 0; k < S; k++) {
      add(tL[k], bL[k], 'vt');
      add(tR[k], bR[k], 'vt');
      add(tL[k], tR[k], 'tr');
      add(bL[k], bR[k], 'tb');
      add(tL[k], bR[k], 'cd');
    }
    return { nodes: nodes, mem: mem };
  }

  let calls = 0;
  function callA(d) {
    if (calls >= CALLMAX || Date.now() - t0 > TLIM) return null;
    calls++;
    try { return analyse(d); } catch (e) { return null; }
  }

  function num(v, dflt) {
    return (typeof v === 'number' && isFinite(v)) ? v : dflt;
  }

  function maxUtilOf(r) {
    let mx = num(r.maxUtil, 0);
    (r.members || []).forEach(function (e) {
      if (e && typeof e.util === 'number' && e.util > mx) mx = e.util;
    });
    return mx;
  }

  function freqOf(r) {
    if (typeof r.frequency === 'number') return r.frequency;
    if (typeof r.fMin === 'number') return r.fMin;
    return null;
  }

  function passes(r) {
    if (!r || r.error || r.ok === false || typeof r.mass !== 'number') return false;
    if (maxUtilOf(r) > UOK) return false;
    if (typeof r.sag === 'number' && r.sag > SAGOK * num(r.sagLimit, 68.8)) return false;
    if (typeof r.sway === 'number' && r.sway > SWOK * num(r.swayLimit, 86)) return false;
    const f = freqOf(r);
    if (f !== null && f < FRQOK) return false;
    if (typeof r.alphaCr === 'number' && r.alphaCr < ACROK) return false;
    if (typeof r.fatigueWorst === 'number' && r.fatigueWorst > FATOK) return false;
    return true;
  }

  function utilMap(r) {
    const map = {};
    (r.members || []).forEach(function (e) {
      if (!e) return;
      if (e.id !== undefined && e.id !== null) map[String(e.id)] = e;
      if (e.a !== undefined && e.b !== undefined) map[e.a + '-' + e.b] = e;
    });
    return map;
  }

  function findE(map, a, b) {
    return map[a + '-' + b] || map[b + '-' + a] || null;
  }

  // Fully-stressed sizing on analyse() utilisations, with one adaptive multiplier Gc on chords
  // (driven by deck sag, sway and frequency, both directions).
  function sizeVariant(V) {
    const T = build(V.fine, V.pratt);
    const mem = T.mem.filter(function (m) { return V.drop.indexOf(m.role) < 0; });
    const n = mem.length;
    const cur = [];
    for (let i = 0; i < n; i++) cur.push(pick(25));

    let Gc = 1.0, best = null;
    for (let it = 0; it < ITER; it++) {
      if (calls >= CALLMAX || Date.now() - t0 > TLIM) break;

      const members = [];
      for (let i = 0; i < n; i++) {
        members.push({ a: mem[i].a, b: mem[i].b, spec: OPTS[cur[i]].spec });
      }
      const d = {
        note: 'Pinned ' + V.name + ' box truss below deck, members sized by fully-stressed iteration on analyse() utilisations.',
        nodes: T.nodes, joints: {}, members: members
      };
      const r = callA(d);
      if (!r || r.error) break;

      if (passes(r) && (best === null || r.mass < best.mass)) {
        best = { mass: r.mass, nodes: T.nodes, members: members, name: V.name };
      }

      // stiffness multiplier for chords, both directions
      let rr = 1;
      if (typeof r.sag === 'number' && r.sag > 0) {
        rr = (r.sag / num(r.sagLimit, 68.8)) / SAGT;
      }
      if (typeof r.sway === 'number') {
        rr = Math.max(rr, (r.sway / num(r.swayLimit, 86)) / SWOK);
      }
      const f = freqOf(r);
      if (f !== null && f < FRQOK + 0.3) {
        rr = Math.max(rr, Math.pow((FRQOK + 0.3) / Math.max(f, 0.1), 2));
      }
      Gc = Math.min(4, Math.max(0.3, Gc * Math.pow(Math.max(rr, 0.05), DAMP)));

      const rm = r.members || [];
      const map = utilMap(r);
      const ents = new Array(n);
      let matched = 0;
      for (let i = 0; i < n; i++) {
        ents[i] = findE(map, mem[i].a, mem[i].b);
        if (ents[i]) matched++;
      }
      const byIndex = (matched === 0 && rm.length === n);

      let changed = false;
      for (let i = 0; i < n; i++) {
        const e = byIndex ? rm[i] : ents[i];
        const u = (e && typeof e.util === 'number') ? e.util : null;
        const sa = OPTS[cur[i]].Sa;
        let need;
        if (u === null) need = sa;
        else need = sa * Math.min(2.5, Math.max(0.3, u / UT));
        const chord = (mem[i].role === 'tc' || mem[i].role === 'bc');
        if (chord) need *= Gc;
        need = Math.max(need, MINSA);
        const j = pick(need);
        if (j !== cur[i]) { cur[i] = j; changed = true; }
      }
      if (!changed) break;
    }
    return best;
  }

  const VARS = [
    { name: 'D-Pratt', fine: false, pratt: true, drop: [] },
    { name: 'F-Pratt', fine: true, pratt: true, drop: [] },
    { name: 'D-Pratt-nocd', fine: false, pratt: true, drop: ['cd'] },
    { name: 'F-Pratt-nocd', fine: true, pratt: true, drop: ['cd'] }
  ];

  let best = null;
  for (let v = 0; v < VARS.length; v++) {
    if (calls >= CALLMAX || Date.now() - t0 > TLIM) break;
    const b = sizeVariant(VARS[v]);
    if (b && (best === null || b.mass < best.mass)) best = b;
  }

  if (best) {
    return {
      note: 'Pinned ' + best.name + ' box truss below deck with top/bottom X-bracing; members sized on analyse() utilisations with an adaptive chord stiffness multiplier to hold deck sag.',
      nodes: best.nodes,
      joints: {},
      members: best.members
    };
  }

  // Fallback: uniform S690 CHS193.7x8 Warren box truss (attempt 5 design, known to pass nominal).
  const TF = build(false, false);
  return {
    note: 'Fallback: uniform S690 CHS193.7x8 Warren box truss (known to pass nominal).',
    nodes: TF.nodes,
    joints: {},
    members: TF.mem.map(function (m) { return { a: m.a, b: m.b, spec: 'S690 CHS193.7x8' }; })
  };
}
